INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(12501, 'koKR', 'Patrol wśród trolli', 'Dobądź broni, $N. Czas na patrol!$b$bMam pod swoim dowództwem cztery posterunki i dla powodzenia naszej sprawy kluczowe jest, by pozostały w naszych rękach. Rozkazuję ci odwiedzić każdy z nich i zaoferować pomoc.$b$bMożesz zacząć od kapitana Brandona, na południowy wschód stąd. Gdy z tobą skończy, wskaże ci kolejny posterunek.$b$bZgłoś się do mnie, gdy pomożesz każdemu z moich ludzi. I pamiętaj: im szybciej wrócisz, tym hojniej zostaniesz $gnagrodzony:nagrodzona; – więc biegiem!$b$bOdmaszerować!', 'Dowódca Kunz w Reducie Argentu każe ci odwiedzić cztery posterunki Krucjaty Argentu, wykonać rozkazy ich dowódców, a potem wrócić i złożyć mu raport.$b$bKapitan Brandon i kapitan Rupert stacjonują w Drak\'Sotra, kapitan Grondel w Drak\'Agal, a alchemik Finklestein w Heb\'Valok.', '', 'Wróć do dowódcy Kunza w Reducie Argentu w Zul\'Draku.', 'Zadanie kapitana Brandona', 'Zadanie kapitana Ruperta', 'Zadanie kapitana Grondela', 'Zadanie alchemika Finklesteina', 0),
(12502, 'koKR', 'Patrol wśród trolli: sztandary w górę', 'Posłuchaj, $N. To jest Krucjata Argentu. Nasi ludzie będą walczyć do końca i nigdy się nie skarżą, bez względu na warunki.$b$bMimo to ponieśliśmy w tej kampanii ciężkie straty, a od miesięcy walczymy bez wytchnienia, prawie bez snu. Wszystko to odbija się na morale, czy się do tego przyznajemy, czy nie.$b$bMoże to niewiele, ale widok naszego sztandaru powiewającego nad polem bitwy jest dla żołnierza sporą pociechą. Weź te sztandary i zatknij je na piedestałach w Drak\'Sotra.', 'Kapitan Brandon chce, by na piedestałach Drakkarów w Drak\'Sotra stanęły sztandary Krucjaty Argentu.', '', 'Wróć do kapitana Brandona w Drak\'Sotra w Zul\'Draku.', 'Sztandar Krucjaty Argentu – południe', 'Sztandar Krucjaty Argentu – północ', 'Sztandar Krucjaty Argentu – wschód', '', 0),
(12503, 'koKR', 'Obrona Reduty', 'Mimo znacznych sukcesów w południowej części Zul\'Draku wciąż musimy stawiać czoła naporowi Plagi. Tak już jest w tym mroźnym piekle.$B$BAtaki nie ustają, a moi ludzie potrzebują odpoczynku. Jeśli zechcesz, przyda się twoja pomoc w ich wsparciu.$B$BNa dziedzińcu poniżej walki nie mają końca. Rozpraw się tam z Plagą z całym zapałem, na jaki cię stać, $N.', 'Dowódca Falstaav zlecił ci zniszczenie 10 dowolnych sług Plagi na dziedzińcu Reduty Argentu.', '', 'Wróć do dowódcy Falstaava w Reducie Argentu w Zul\'Draku.', 'Zniszczeni słudzy Plagi w Reducie Argentu', '', '', '', 0),
(12504, 'koKR', 'Krucjato Argentu, wycofujemy się!', '<Sierżant szybko przegląda rozkazy, które mu $gwręczyłeś:wręczyłaś;, a jego twarz się chmurzy.>$B$BSłuchaj, $gchłopcze:dziewczyno;, najchętniej od razu bym się zwinął, ale spójrz tam. Wszyscy moi ludzie walczą.$B$BWiesz co, skoro już tu $gdotarłeś:dotarłaś;, może $gzrobiłbyś:zrobiłabyś; mi drobną przysługę? Idź tam i zbierz moich żołnierzy.$B$BPowiedz im, że sierżant rozkazuje im natychmiast się zameldować. I pomóż im, jeśli możesz.', 'Sierżant Stosomłot przy Ołtarzu Sseratusa prosi, by przekazać 10 jego żołnierzom Argentu rozkaz powrotu.', '', 'Wróć do sierżanta Stosomłota przy Ołtarzu Sseratusa w Zul\'Draku.', 'Żołnierze Argentu wezwani do powrotu do sierżanta', '', '', '', 0),
(12505, 'koKR', 'Nowe rozkazy dla sierżanta Stosomłota', '$N, jesteś tu, żeby pomóc, prawda? Mam nowe rozkazy dla naszych sił rozmieszczonych obecnie przy ołtarzu Drakkarów na północy.$B$BNie da się go przeoczyć. Idź prosto aleją w górę. Sierżanta Stosomłota nie powinno być trudno znaleźć.', 'Dowódca Kunz poprosił cię o dostarczenie nowych rozkazów przegrupowania sierżantowi Stosomłotowi przy Ołtarzu Sseratusa.', '', 'Wróć do sierżanta Stosomłota w Lodowatym Wyłomie w Zul\'Draku.', '', '', '', '', 0),
(12506, 'koKR', 'Kłopoty przy Ołtarzu Sseratusa', 'Przy ołtarzu boga węży dzieje się coś złego.$B$BObecność Plagi osłabiła ziemię, $N. To z kolei osłabiło dzikich bogów.$B$BWiemy, że Drakkarowie to wykorzystują, by czynić bogom zło.$B$BMusisz być moimi oczami i uszami. Ołtarz Sseratusa jest na końcu alei, na północy. Zakradnij się od tyłu i zajrzyj do wnętrza głównej budowli ołtarza.$B$BCokolwiek zrobisz, za wszelką cenę unikaj proroka!', 'Rzucacz uroków Ubungo w Reducie Argentu poprosił cię o zbadanie głównej budowli przy Ołtarzu Sseratusa.', 'Główna budowla przy Ołtarzu Sseratusa zbadana.', 'Wróć do rzucacza uroków Ubungo w Reducie Argentu w Zul\'Draku.', '', '', '', '', 0),
(12507, 'koKR', 'Dziwne mojo', 'Ta butelka dziwnego mojo może być kluczem do tego, co tu się naprawdę dzieje.$B$BZandalarski troll, rzucacz uroków Ubungo z Reduty Argentu, może zechcieć jej się przyjrzeć.', 'Dostarcz dziwne mojo rzucaczowi uroków Ubungo w Reducie Argentu.', '', 'Wróć do rzucacza uroków Ubungo na Martwych Polach w Zul\'Draku.', '', '', '', '', 0),
(12508, 'koKR', 'Czystka', 'Nie mogłam nie usłyszeć, o czym $grozmawiałeś:rozmawiałaś; z sierżantem. To nie zmienia faktu, że wciąż mamy tu robotę do wykonania.$B$BSkoro już tam będziesz, $gpomógłbyś:pomogłabyś; nam skrócić męki kilku wyznawcom Sseratusa?', 'Kapral Maga przy Ołtarzu Sseratusa chce, żebyś $gzabił:zabiła; łącznie 10 czempionów Sseratusa, kapłanów Sseratusa lub treserów węży Drakkarów.', '', 'Wróć do kapral Magi przy Ołtarzu Sseratusa w Zul\'Draku.', 'Zabici wyznawcy Sseratusa', '', '', '', 0),
(12509, 'koKR', 'Patrol wśród trolli: hart ducha', 'Nareszcie patrol!$b$bSytuacja wygląda tak, $N. W tej kampanii straciliśmy wielu naszych najlepszych żołnierzy i musieliśmy łatać luki rekrutami.$b$bWłaśnie stoczyliśmy jedną z najzacieklejszych bitew i wielu rekrutów po prostu nie było gotowych na starcie z takim wrogiem. Przed nami kolejne walki i potrzebuję ich gotowych do wykonywania rozkazów.$b$bJeśli czegoś nie mogę strawić, to tchórzostwa. Może pomożesz im odnaleźć odwagę, by walczyć dalej.', 'Kapitan Rupert w Drak\'Sotra prosi o przywrócenie odwagi skulonym ze strachu rekrutom krucjaty.', '', 'Wróć do kapitana Ruperta w Drak\'Sotra w Zul\'Draku.', 'Odwaga rekrutów przywrócona', '', '', '', 0),
(12510, 'koKR', 'Cenne płyny żywiołów', '<Rzucacz uroków bada karafkę z mojo.>$B$BMam pomysł, jak poradzić sobie z prorokiem Sseratusa. Ale najpierw będziemy potrzebować kilku rzeczy.$B$BPola Drak\'Sotra leżą prosto na południe. Przez udrękę, jaką ziemi zadaje Plaga, i przez śmierć bogów mur między światami osłabł, a żywiołaki wlewają się tutaj.$B$BPotrzebujemy cennych płynów ich władców. Jeśli połączysz trzy więzi żywiołaków, powstanie więź z ich planem i będzie można przywołać jednego z władców.', 'Rzucacz uroków Ubungo w Reducie Argentu chce, żebyś $gzdobył:zdobyła; 3 cenne płyny żywiołów.', '', 'Wróć do rzucacza uroków Ubungo w Reducie Argentu w Zul\'Draku.', '', '', '', '', 0),
(12512, 'koKR', 'Nikogo nie zostawiamy', 'Ach, dobrze. Kogoś przysłali.$b$bSłuchaj, $N. Potrzebujemy tu pomocy. Nasze siły zostały odparte i straciliśmy Drak\'Sotra na rzecz Plagi. Skąd się tu wzięli, nikt nie wie...$b$bChodzi o to, że potrzebujemy tu każdego człowieka, a kilku naszych najlepszych jeszcze nie wróciło z bitwy.$b$bSkoro walki przycichły, musisz wejść do ruin, odnaleźć naszych rannych, opatrzyć ich i przyprowadzić do mnie.$b$bPrzeszukaj Drak\'Sotra! Nie mogli odejść daleko.', 'Doktor Rogers w Drak\'Sotra chce, żebyś $godnalazł:odnalazła; krzyżowca Lamoofa, krzyżowca Jonathana i krzyżowczynię Josephine. Użyj na nich bandaża krzyżowca i bezpiecznie odprowadź ich do niego.', '', 'Wróć do doktora Rogersa w Drak\'Sotra w Zul\'Draku.', 'Uratowany krzyżowiec Jonathan', 'Uratowany krzyżowiec Lamoof', 'Uratowana krzyżowczyni Josephine', '', 0),
(12514, 'koKR', 'Grzybowa mikstura', 'Teraz potrzebujemy czegoś, czym doprawimy mojo. Czegoś, co sprawi, że gdy prorok je wypije, straci część mocy.$B$BNa wschodzie leży Drak\'Agal. Rośnie tam grzyb, który tubylcy nazywają mącigłówką. Myślę, że to dokładnie to, czego nam trzeba.$B$BPrzynieś ich dużo. Gdy wmieszamy je w mojo, każdemu, kto je wypije, zamąci się w głowie.', 'Zbierz 10 grzybów mącigłówek i dostarcz je rzucaczowi uroków Ubungo w Reducie Argentu.', '', 'Wróć do rzucacza uroków Ubungo w Reducie Argentu w Zul\'Draku.', '', '', '', '', 0),
(12516, 'koKR', 'Co za dużo, to niezdrowo', 'Proszę. Zmodyfikowałem mojo. Teraz, gdy prorok je wypije, nie tylko straci część mocy, ale grzyby zamącą mu też w głowie.$B$BPrzynajmniej w teorii.$B$BA jak sprawić, żeby je wypił? Może po prostu w niego rzuć? Przy tej arogancji, jaką popisuje się przy ołtarzu, na pewno je złapie i wypije.$B$BJeśli go nie zabijesz, $N, twoją Krucjatę Argentu czeka straszny koniec.', 'Zabij otumanionego proroka Sseratusa, a następnie wróć do rzucacza uroków Ubungo w Reducie Argentu.', '', 'Wróć do rzucacza uroków Ubungo w Reducie Argentu w Zul\'Draku.', '', '', '', '', 0),
(12519, 'koKR', 'Patrol wśród trolli: a co, medal chcesz?', 'Spójrz na mnie, $N. Czy ja wyglądam, jakbym miał czas na wypełnianie raportów?$b$bLedwo daję radę utrzymać ten posterunek wolny od cholernej Plagi, a oni chcą, żebym się bawił w papierki!$b$b<wzdycha> Nie ma co narzekać. Muszę dostarczyć dowódcy jakąś liczbę zabitych z ostatniej potyczki.$b$bChcesz się na coś przydać? Idź i przynieś mi wszystkie medaliony, jakie znajdziesz przy martwych trollach w okolicy. To musi wystarczyć.', 'Kapitan Grondel przed koloseum chce, żebyś $gzebrał:zebrała; 7 medalionów Drakkarów ze zwłok Drakkarów w okolicy.', '', 'Wróć do kapitana Grondela przy Amfiteatrze Męczarni w Zul\'Draku.', '', '', '', '', 0),
(12527, 'koKR', 'Żarłoczne bazyliszki', 'Mój mistrz, Finklestein, jest w świątyni w Heb\'Valok na północnym zachodzie i przygotowuje serum prawdy, a potrzebuje do niego kryształów bazyliszka. Heb\'Valok leży po zachodniej stronie drogi prowadzącej na północ, przed Ołtarzem Sseratusa.$B$BNa wschodzie, w Drak\'Agal, są bazyliszki.$B$BJeśli złapiesz szczury z Zul\'Draku i będziesz nimi rzucać w bazyliszka, po zjedzeniu pięciu się obeżre i stanie się potulny. Wtedy będzie można zabrać mu kryształy.$B$BZabicie bazyliszka nic ci nie da. Tylko potłuczesz mu kryształy!', 'Dostarcz 5 kryształów bazyliszka alchemikowi Finklesteinowi w świątyni w Heb\'Valok.', '', 'Wróć do alchemika Finklesteina w świątyni w Heb\'Valok w Zul\'Draku.', '', '', '', '', 0),
(12541, 'koKR', 'Patrol wśród trolli: uczeń alchemika', 'Ach, to pewnie ty jesteś obiecanym patrolem. Nie mogło się lepiej złożyć. Pilnie potrzebuję dodatkowej pary rąk.$b$bMamy pojmanego Drakkara, którego przysłano tu na przesłuchanie. Zanim je zaczniemy, potrzebuję pomocy w sporządzeniu serum prawdy.$b$bSporządzanie serum prawdy to podchwytliwa sprawa, która wymaga bystrego instynktu, doskonałego wyczucia czasu i improwizacji na każdym kroku.$b$bDaj znać, gdy będziesz $ggotowy:gotowa;, $N. I pamiętaj: wyczucie czasu to podstawa!$B', 'Alchemik Finklestein w Heb\'Valok chce, żebyś $gpomógł:pomogła; mu w sporządzeniu serum prawdy.$b$bGdy będziesz $ggotowy:gotowa; zacząć, porozmawiaj z nim i postępuj zgodnie z jego wskazówkami.', '', 'Wróć do alchemika Finklesteina w Heb\'Valok w Zul\'Draku.', 'Serum prawdy sporządzone', '', '', '', 0),
(12552, 'koKR', 'Śmierć nekromagom', 'Kiedy trolle strąciły Kolramas, nekropolia runęła obok nas, na południowym wschodzie. Niestety, katastrofa nie zniszczyła całej Plagi w środku.$B$BTeraz wskrzeszają naszych poległych i wykorzystują ich przeciwko nam!$B$BNa to nie pozwolimy. Dopilnujesz, żeby ich nekromagowie zostali wyrżnięci! Czy wyrażam się jasno?', 'Sierżant Księżycowy Odłamek w Drak\'Sotra poprosił cię o zniszczenie 8 nekromagów Hath\'ar.', '', 'Wróć do sierżanta Księżycowego Odłamka w Drak\'Sotra w Zul\'Draku.', '', '', '', '', 0),
(12553, 'koKR', 'Kądziołki ślizgaczy', 'Czemu to zawsze mnie trafiają się najtrudniejsze zadania?$B$BPlaga w Kolramas ma rozpylacze zarazy, które podlatują niebezpiecznie blisko. Nie chcesz wiedzieć, co się stanie, jeśli ruszą w tę stronę!$B$BMam pomysł, jak je strącić, ale najpierw będziemy potrzebować czegoś... czegoś od ich własnych stworów.$B$BŚlizgacze Hath\'ar potrafią przędzić bardzo mocną sieć, którą możemy dobrze wykorzystać. Przynieś kilka ich kądziołek.', 'Specjalistka Zębatka w Drak\'Sotra poprosiła cię o zebranie 5 nienaruszonych kądziołek ślizgaczy.', '', 'Wróć do specjalistki Zębatki w Drak\'Sotra w Zul\'Draku.', '', '', '', '', 0),
(12554, 'koKR', 'Malas Skaziciel', '$N, zbierz przynajmniej jeszcze jedną osobę i wracaj tam na dół!$B$BPrzywódcę Kolramas, Malasa Skaziciela, znajdziesz na szczycie rozbitej nekropolii, gdzie napawa się triumfem.$B$BZabij go i przynieś mi jego głowę!', 'Sierżant Księżycowy Odłamek w Drak\'Sotra nalega, byś $gwrócił:wróciła; z głową Skaziciela.', '', 'Wróć do sierżanta Księżycowego Odłamka w Drak\'Sotra w Zul\'Draku.', '', '', '', '', 0),
(12555, 'koKR', 'Splątana przędza', 'Gotowe! Miotacz splątanej przędzy czeka, aż strącisz nim te rozpylacze zarazy.$B$BWystarczy wycelować i strzelić. Sieć powinna zakłócić ich zaklęcia lewitacji na tyle długo, żeby runęły na ziemię, tak jak Kolramas.$B$BTo nawet poetyckie. Podoba mi się!', 'Specjalistka Zębatka w Drak\'Sotra poprosiła cię o użycie miotacza splątanej przędzy, by zniszczyć 5 rozpylaczy zarazy.', '', 'Wróć do specjalistki Zębatki w Drak\'Sotra w Zul\'Draku.', 'Rozpylacze zarazy oplecione siecią i zniszczone', '', '', '', 0),
(12557, 'koKR', 'Praca w laboratorium', 'Zakładam, że skoro mi przerywasz, chcesz się znaleźć wśród tych, których biorę pod uwagę jako uczniów.$b$bGodna aspiracja...$b$bJeśli kiedyś zdecyduję się przyjąć twoją prośbę, muszę mieć pewność, że potrafisz poruszać się po moim laboratorium. Mam tu wiele składników; niektórych pod dostatkiem, innych niewiele.$b$bNie spiesz się, $N. Znajdź błotnistego czerwia z grzęzawiska, zasuszone skrzydło nietoperza, bursztynowe nasiono i trochę schłodzonego wężowego śluzu.$b$bJeśli ci się uda, będę wiedział, że twoją prośbę należy traktować poważnie.', 'Alchemik Finklestein w Heb\'Valok chce, żebyś $godnalazł:odnalazła; w jego laboratorium błotnistego czerwia z grzęzawiska, zasuszone skrzydło nietoperza, bursztynowe nasiono i trochę schłodzonego wężowego śluzu.', '', 'Wróć do alchemika Finklesteina w Heb\'Valok w Zul\'Draku.', 'Błotnisty czerw z grzęzawiska znaleziony', 'Zasuszone skrzydło nietoperza znalezione', 'Bursztynowe nasiono znalezione', 'Schłodzony wężowy śluz znaleziony', 0),
(12562, 'koKR', 'Drakkarom nie są potrzebne wodne żywiołaki!', 'Wywiad donosi, że odkąd na Polach Drak\'Sotra pojawiły się wodne żywiołaki, z wyższych poziomów Zul\'Draku zeszło kilku szamanów Drakkarów, by przejąć nad nimi kontrolę.$B$BNie potrafię dość mocno podkreślić, $gpanie:pani;, jakie to może być niebezpieczne. Nie chcemy, żeby mieli do dyspozycji wodne żywiołaki.$B$BDowódca rozkazał, by tych wiążących wodę Drakkarów wyciąć w pień. Gdy będziesz $ggotowy:gotowa;, ruszaj na południe.', 'Podporucznik Jax w Reducie Argentu poprosiła cię o zabicie 10 wiążących wodę Drakkarów.', '', 'Wróć do podporucznik Jax w Reducie Argentu w Zul\'Draku.', '', '', '', '', 0),
(12563, 'koKR', 'Patrol wśród trolli', 'Dobądź broni, $N. Czas na patrol!$b$bMam pod swoim dowództwem cztery posterunki i dla powodzenia naszej sprawy kluczowe jest, by pozostały w naszych rękach. Rozkazuję ci odwiedzić każdy z nich i zaoferować pomoc.$b$bMożesz zacząć od kapitana Brandona, na południowy wschód stąd. Gdy z tobą skończy, wskaże ci kolejny posterunek.$b$bZgłoś się do mnie, gdy pomożesz każdemu z moich ludzi. I pamiętaj: im szybciej wrócisz, tym hojniej zostaniesz $gnagrodzony:nagrodzona; – więc biegiem!$b$bOdmaszerować!', 'Dowódca Kunz w Reducie Argentu każe ci odwiedzić cztery posterunki Krucjaty Argentu, wykonać rozkazy ich dowódców, a potem wrócić i złożyć mu raport.$b$bKapitan Brandon i kapitan Rupert stacjonują w Drak\'Sotra, kapitan Grondel w Drak\'Agal, a alchemik Finklestein w Heb\'Valok.', '', 'Wróć do dowódcy Kunza w Reducie Argentu w Zul\'Draku.', 'Zadanie kapitana Brandona', 'Zadanie kapitana Ruperta', 'Zadanie kapitana Grondela', 'Zadanie alchemika Finklesteina', 0),
(12564, 'koKR', 'Patrol wśród trolli: coś na ból', 'Moi ludzie są twardzi, ale wciąż są śmiertelni.$b$bRany i ból osłabiają ich zdolność do wykonywania zadań. Żadne szkolenie nie zmieni tej prostej prawdy.$b$bNa szczęście jeden z naszych alchemików opracował recepturę maści, która wiąże się z bandażami i znacznie łagodzi ból, jaki odczuwają nasi żołnierze.$b$bDo maści potrzebny jest szczególny mak, który te trolle uprawiają tuż na zachód stąd. Idź na Pola Drak\'Sotra i zbierz go trochę, żeby nie wyczerpały się nam zapasy.', 'Kapitan Brandon w Drak\'Sotra chce, żebyś $gzebrał:zebrała; 5 dojrzałych wodnych maków na Polach Drak\'Sotra.', '', 'Wróć do kapitana Brandona w Drak\'Sotra w Zul\'Draku.', '', '', '', '', 0),
(12565, 'koKR', 'Błogosławieństwo Zim\'Abwy', 'Cieszy mnie zapał, z jakim twoja Krucjata Argentu rozprawia się z Plagą, $N. Chciałbym wesprzeć wasze wysiłki.$B$BDrakkarowie z tego niegdyś wielkiego miasta regularnie składali ofiary swoim bogom, ale teraz o nich zapominają, albo gorzej.$B$BGdybyś $gzłożył:złożyła; bogom ofiary, okazaliby ci w zamian swoją wdzięczność.$B$BPosąg Zim\'Abwy stoi tuż na południowy zachód stąd. Zim\'Abwa chętnie przyjmie w ofierze artefakty Drakkarów jako znak, że chronisz Zul\'Drak.', 'Rzucacz uroków Ubungo w Reducie Argentu chce, żebyś $gzłożył:złożyła; 10 ofiar Drakkarów przed posągiem Zim\'Abwy.', '', 'Dostarcz ofiary Drakkarów Zim\'Abwie, na południowy zachód od Reduty Argentu w Zul\'Draku.', '', '', '', '', 0),
(12567, 'koKR', 'Błogosławieństwo Zim\'Abwy', '', '', '', 'Wróć do Zim\'Abwy w Zul\'Draku.', '', '', '', '', 0),
(12568, 'koKR', 'Patrol wśród trolli: ostatnia posługa', 'Uwierz mi, $N. Wiem...$b$bOd smrodu palonego ciała robi się niedobrze nawet mnie, Porzuconemu. Mimo to naszym uroczystym obowiązkiem jest dopilnować, by nasi bracia nigdy nie kroczyli u boku Plagi.$b$bPolej tym olejem zwłoki naszych poległych, byśmy nigdy nie musieli stanąć z nimi na polu bitwy jak z wrogami.', 'Kapitan Rupert chce, żebyś $gużył:użyła; oleju spopielającego na 5 pokonanych piechurach Argentu w Drak\'Sotra.', '', 'Wróć do kapitana Ruperta w Drak\'Sotra w Zul\'Draku.', 'Spalone zwłoki piechura Argentu', '', '', '', 0),
(12583, 'koKR', 'Rozbity rozpylacz', 'Wiem, że jeden z tych rozpylaczy zarazy rozbił się gdzieś w Drak\'Sotra, na zachód od nas.$B$BMoże spróbujesz go znaleźć? Z części rozpylacza zbuduję urządzenie, którym strącimy te paskudztwa!', 'Specjalistka Zębatka w Drak\'Sotra poprosiła cię o zebranie części rozpylacza zarazy.', '', 'Wróć do specjalistki Zębatki w Drak\'Sotra w Zul\'Draku.', '', '', '', '', 0),
(12584, 'koKR', 'Czyste zło', 'Wiemy, że Kolramas, rozbita nekropolia na południowym wschodzie, przewoziła mnóstwo rudy zwanej saronitem, gdy trolle ją zestrzeliły.$B$BMoi zwiadowcy mówią, że sporo saronitu leży porozrzucane w trzewiach tego czegoś.$B$BEitrigg i jego przyjaciele w Reducie Argentu chcą dostać go sporo, żeby go zbadać.$B$BIdź tam i zobacz, czy uda ci się zebrać dla nich dość.', 'Kapitan Rupert poprosił cię o zebranie 10 brył saronitu i dostarczenie ich Eitriggowi w Reducie Argentu.', '', 'Wróć do Eitrigga w Reducie Argentu w Zul\'Draku.', '', '', '', '', 0),
(12585, 'koKR', 'Patrol wśród trolli: odrobina wygody', 'No, nie jest to zaszczytne, ale trzeba to zrobić.$b$bMoi żołnierze od wielu dni walczą z całych sił, brodząc po kolana w stojącej wodzie. To nie może wyjść na zdrowie.$b$bPotrzebują porządnego ognia, żeby się osuszyć i podnieść na duchu.$b$bTa część miasta jest przemoczona, ale martwe korzenie tych cierniodrzew jakoś opierają się wilgoci.$b$bNazbieraj nam trochę opału, a będziemy ci szczerze wdzięczni.', 'Kapitan Grondel w Drak\'Agal chce, żebyś $gprzyniósł:przyniosła; mu 20 kawałków martwego cierniodrzewa.', '', 'Wróć do kapitana Grondela w Drak\'Agal w Zul\'Draku.', '', '', '', '', 0),
(12587, 'koKR', 'Patrol wśród trolli', 'Dobądź broni, $N. Czas na patrol!$b$bMam pod swoim dowództwem cztery posterunki i dla powodzenia naszej sprawy kluczowe jest, by pozostały w naszych rękach. Rozkazuję ci odwiedzić każdy z nich i zaoferować pomoc.$b$bMożesz zacząć od kapitana Brandona, na południowy wschód stąd. Gdy z tobą skończy, wskaże ci kolejny posterunek.$b$bZgłoś się do mnie, gdy pomożesz każdemu z moich ludzi. I pamiętaj: im szybciej wrócisz, tym hojniej zostaniesz $gnagrodzony:nagrodzona; – więc biegiem!$b$bOdmaszerować!', 'Dowódca Kunz w Reducie Argentu każe ci odwiedzić cztery posterunki Krucjaty Argentu, wykonać rozkazy ich dowódców, a potem wrócić i złożyć mu raport.$b$bKapitan Brandon i kapitan Rupert stacjonują w Drak\'Sotra, kapitan Grondel w Drak\'Agal, a alchemik Finklestein w Heb\'Valok.', '', 'Wróć do dowódcy Kunza w Reducie Argentu w Zul\'Draku.', 'Zadanie kapitana Brandona', 'Zadanie kapitana Ruperta', 'Zadanie kapitana Grondela', 'Zadanie alchemika Finklesteina', 0),
(12588, 'koKR', 'Patrol wśród trolli: wykopki', 'Jeden z naszych żołnierzy znalazł podczas ostatniej ofensywy starą mapę skarbów. Jeśli to, co pokazuje, jest prawdą, w pobliżu są bezcenne artefakty trolli.$b$bMoi żołnierze mają pełne ręce roboty, wciśnięci między Drakkarów a Plagę. Musisz sprawdzić ten trop.$b$bWeź ten szpadel i użyj go na kopcach luźnej ziemi na południowym zachodzie. Wróć do mnie, gdy dokładnie je przeszukasz.', 'Kapitan Brandon w Drak\'Sotra chce, żebyś $gużył:użyła; stalowego szpadla na pobliskich pradawnych kopcach ziemi, by odzyskać pradawną relikwię Drakkarów.', '', 'Wróć do kapitana Brandona w Drak\'Sotra w Zul\'Draku.', 'Pradawne kopce ziemi zbadane', '', '', '', 0),
(12591, 'koKR', 'Patrol wśród trolli: granaty w dół', 'Sprytne...$b$bGdy już się wydawało, że panujemy nad sytuacją, przekopali się tuż pod nami i zajęli świątynię!$b$bTeraz jesteśmy w potrzasku między dwiema armiami nerubian, a nasze położenie z minuty na minutę się pogarsza.$b$bNajpierw musimy powstrzymać ich przed ściąganiem posiłków. Ich tunele trzeba zasypać.$b$bWeź te granaty i wrzuć je do ich kraterów na północnym zachodzie.', 'Kapitan Rupert w Drak\'Sotra chce, żebyś $gużył:użyła; granatów o dużej sile rażenia przy 5 kraterach nerubian.', '', 'Wróć do kapitana Ruperta w Drak\'Sotra w Zul\'Draku.', 'Tunele nerubian zawalone', '', '', '', 0),
(12594, 'koKR', 'Patrol wśród trolli: wszystko mi jedno', 'Ze wszystkich posterunków musieli mnie wrzucić akurat na ten.$b$bTo miejsce jest zalane cuchnącą, stojącą wodą, a teraz jeszcze zalęgły się tu żywiołaki ścieków!$b$bNie bardzo wiem, czym są ani skąd się tu wzięły, i szczerze mówiąc, wszystko mi jedno. Wiem natomiast, że robią bałagan w moim sektorze! Jak mam prowadzić jakiekolwiek godne operacje wojskowe, gdy te paskudztwa się tu szwendają?$b$bRuszaj, $N, i nie wracaj, dopóki nie usuniesz z mojego pola bitwy swojej części tych stworów!', 'Kapitan Grondel chce, żebyś $gzabił:zabiła; 7 omszałych szarżozwierzy w Drak\'Agal.', '', 'Wróć do kapitana Grondela przy Amfiteatrze Męczarni w Zul\'Draku.', 'Zabite omszałe szarżozwierze', '', '', '', 0),
(12596, 'koKR', 'Pa\'trol', 'Witaj w Reducie Argentu, żółtodziobie. Jestem dowódca Kunz, ale ty... ty możesz się do mnie zwracać... dowódco.$b$bNie myśl sobie, że będziesz się beztrosko przechadzać po moim rejonie, wybierać, w których misjach weźmiesz udział, i przed nikim nie odpowiadać.$b$bTutaj meldujesz się u mnie i wykonujesz moje rozkazy co do joty. Zrozumiano?!$b$bNajpierw zapoznasz się z moimi ludźmi i z rejonem, który mamy oczyścić.$b$bZamelduj się u każdego z nich i rób, co każą. Wróć do mnie, gdy skończysz patrol.', 'Dowódca Kunz w Reducie Argentu każe ci odwiedzić cztery posterunki Krucjaty Argentu, wykonać rozkazy ich dowódców, a potem wrócić i złożyć mu raport.$b$bKapitan Brandon i kapitan Rupert stacjonują w Drak\'Sotra, na południowy wschód stąd.$b$bKapitan Grondel stacjonuje w Drak\'Agal, prosto na wschód.$b$bAlchemik Finklestein stacjonuje w Heb\'Valok, na północy.', '', 'Wróć do dowódcy Kunza w Reducie Argentu w Zul\'Draku.', 'Zadanie kapitana Brandona', 'Zadanie kapitana Ruperta', 'Zadanie kapitana Grondela', 'Zadanie alchemika Finklesteina', 0),
(12597, 'koKR', 'Coś na ból', 'Moi ludzie są twardzi, ale wciąż są śmiertelni.$b$bRany i ból osłabiają ich zdolność do wykonywania zadań. Żadne szkolenie nie zmieni tej prostej prawdy.$b$bNa szczęście jeden z naszych alchemików opracował recepturę maści, która wiąże się z bandażami i znacznie łagodzi ból, jaki odczuwają nasi żołnierze.$b$bDo maści potrzebny jest szczególny mak, który te trolle uprawiają tuż na zachód stąd. Idź na Pola Drak\'Sotra i zbierz go trochę, żeby nie wyczerpały się nam zapasy.', 'Kapitan Brandon w Drak\'Sotra chce, żebyś $gzebrał:zebrała; 5 dojrzałych wodnych maków na Polach Drak\'Sotra.', '', 'Wróć do kapitana Brandona w Drak\'Sotra w Zul\'Draku.', '', '', '', '', 0),
(12598, 'koKR', 'Granaty w dół', 'Sprytne...$b$bGdy już się wydawało, że panujemy nad sytuacją, przekopali się tuż pod nami i zajęli świątynię!$b$bTeraz jesteśmy w potrzasku między dwiema armiami nerubian, a nasze położenie z minuty na minutę się pogarsza.$b$bNajpierw musimy powstrzymać ich przed ściąganiem posiłków. Ich tunele trzeba zasypać.$b$bWeź te granaty i wrzuć je do ich kraterów na północnym zachodzie.', 'Kapitan Rupert w Drak\'Sotra chce, żebyś $gużył:użyła; granatów o dużej sile rażenia przy 5 kraterach nerubian.', '', 'Wróć do kapitana Ruperta w Drak\'Sotra w Zul\'Draku.', 'Tunele nerubian zasypane', '', '', '', 0),
(12599, 'koKR', 'Odrobina wygody', 'No, nie jest to zaszczytne, ale trzeba to zrobić.$b$bMoi żołnierze od wielu dni walczą z całych sił, brodząc po kolana w stojącej wodzie. To nie może wyjść na zdrowie.$b$bPotrzebują porządnego ognia, żeby się osuszyć i podnieść na duchu.$b$bTa część miasta jest przemoczona, ale martwe korzenie tych cierniodrzew jakoś opierają się wilgoci.$b$bNazbieraj nam trochę opału, a będziemy ci szczerze wdzięczni.', 'Kapitan Grondel w Drak\'Agal chce, żebyś $gprzyniósł:przyniosła; mu 20 kawałków martwego cierniodrzewa.', '', 'Wróć do kapitana Grondela w Drak\'Agal w Zul\'Draku.', '', '', '', '', 0),
(12601, 'koKR', 'Uczeń alchemika', 'Ach, to pewnie ty jesteś obiecanym patrolem. Nie mogło się lepiej złożyć. Pilnie potrzebuję dodatkowej pary rąk.$b$bMamy pojmanego Drakkara, którego przysłano tu na przesłuchanie. Zanim je zaczniemy, potrzebuję pomocy w sporządzeniu serum prawdy.$b$bSporządzanie serum prawdy to podchwytliwa sprawa, która wymaga bystrego instynktu, doskonałego wyczucia czasu i improwizacji na każdym kroku.$b$bDaj znać, gdy będziesz $ggotowy:gotowa;, $N. I pamiętaj: wyczucie czasu to podstawa!', 'Alchemik Finklestein w Heb\'Valok chce, żebyś $gpomógł:pomogła; mu w sporządzeniu serum prawdy.$b$bGdy będziesz $ggotowy:gotowa; zacząć, porozmawiaj z nim i postępuj zgodnie z jego wskazówkami.', '', 'Wróć do alchemika Finklesteina w Relikwiarzu Bólu w Zul\'Draku.', 'Serum prawdy sporządzone', '', '', '', 0),
(12602, 'koKR', 'Uczeń alchemika', 'Ach, to pewnie ty jesteś obiecanym patrolem. Nie mogło się lepiej złożyć. Pilnie potrzebuję dodatkowej pary rąk.$b$bMamy pojmanego Drakkara, którego przysłano tu na przesłuchanie. Zanim je zaczniemy, potrzebuję pomocy w sporządzeniu serum prawdy.$b$bSporządzanie serum prawdy to podchwytliwa sprawa, która wymaga bystrego instynktu, doskonałego wyczucia czasu i improwizacji na każdym kroku.$b$bDaj znać, gdy będziesz $ggotowy:gotowa;, $N. I pamiętaj: wyczucie czasu to podstawa!', 'Alchemik Finklestein w Heb\'Valok chce, żebyś $gpomógł:pomogła; mu w sporządzeniu serum prawdy.$b$bGdy będziesz $ggotowy:gotowa; zacząć, porozmawiaj z nim i postępuj zgodnie z jego wskazówkami.', '', 'Wróć do alchemika Finklesteina w Relikwiarzu Bólu w Zul\'Draku.', 'Serum prawdy sporządzone', '', '', '', 0),
(12604, 'koKR', 'Gratulacje!', '', '', '', '', '', '', '', '', 0),
(12606, 'koKR', 'W kokonach!', 'Skoro tunele zostały zasypane, teraz musimy odzyskać tych, którzy wpadli w ręce wroga.$b$bJeśli dopisze nam szczęście, kilku naszych żołnierzy wciąż żyje i jest w niezłym stanie wewnątrz nerubiańskich kokonów.$b$bUwolnij ich, $N, póki jeszcze możesz!', 'Kapitan Rupert chce, żebyś $gotworzył:otworzyła; nerubiańskie kokony w Drak\'Sotra i $gwrócił:wróciła; do niego, gdy uwolnisz 3 uwięzionych piechurów.', '', 'Wróć do kapitana Ruperta w Drak\'Sotra w Zul\'Draku.', 'Uwolnieni piechurzy', '', '', '', 0),
(12609, 'koKR', 'Uzupełnianie półek', 'Posłuchaj, $N. Zdaję sobie sprawę, że proszę o wiele...$b$bŚwieżą pajęczą posokę niełatwo zdobyć, nawet w tych rojących się od robactwa rejonach. Ale Finklestein oznajmił, że nie zadowoli się niczym mniej niż całą kadzią i że potrzebuje jej szybko.$b$bMoi ludzie nadal będą zbierać odczynniki w terenie, ale jeśli zamówienie alchemika ma zostać zrealizowane na czas, będą potrzebować pomocy.$b$bKiedy będziesz przemierzać pola Zul\'Draku, wypatruj pełzaczy zapadniowych i przynieś mi całą posokę, jaką znajdziesz.', 'Kapitan Arnath w Heb\'Valok poprosił cię o zebranie 7 porcji świeżej pajęczej posoki z pełzaczy zapadniowych w Zul\'Draku.', '', 'Wróć do kapitana Arnatha w Heb\'Valok w Zul\'Draku.', '', '', '', '', 0),
(12610, 'koKR', 'Podcinanie skrzydeł', 'Odkąd przybył Finklestein, zostałem zdegradowany do zbierania różnych składników do jego eksperymentów i receptur.$b$bBędę wykonywał rozkazy, tak jak przysięgałem, ale jestem doświadczonym weteranem. Brałem udział w dziesiątkach konfliktów. Wolałbym być na pierwszej linii i mieć bardziej bezpośredni wpływ na losy Krucjaty tutaj.$b$bPomóż mi, $N. Zbierz dla mnie trochę skrzydeł nietoperzy, żebym mógł szybciej wrócić do prawdziwej walki.', 'Kapitan Arnath w Heb\'Valok poprosił cię o zdobycie 7 nieskazitelnych skrzydeł nietoperza od nietoperzy z Zul\'Draku.', '', 'Wróć do kapitana Arnatha w Heb\'Valok w Zul\'Draku.', '', '', '', '', 0),
(12615, 'koKR', 'Błogosławieństwo Zim\'Torgi', 'Rzucacz uroków Ubungo pewnie mówił ci o składaniu ofiar bogom Zul\'Draku. Zim\'Abwa nie jest jedynym bogiem zapomnianym przez Drakkarów.$B$BSchroniliśmy się w obecności Zim\'Torgi, Matki Dobrobytu. Tak jak w przypadku Zim\'Abwy, jeśli złożysz jej ofiary Drakkarów, na pewno udzieli ci swojego błogosławieństwa.', 'Znachor Khufu chce, żebyś $gzłożył:złożyła; 10 ofiar Drakkarów przed posągiem Zim\'Torgi.', '', 'Dostarcz ofiary Drakkarów Zim\'Tordze w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12618, 'koKR', 'Błogosławieństwo Zim\'Torgi', '', '', '', 'Wróć do Zim\'Torgi w Zul\'Draku.', '', '', '', '', 0),
(12622, 'koKR', 'Przywódcy z Jin\'Alai', 'Myślisz to samo co Ahunae, mon?$B$BCzęść Drakkarów zebrała się przy Sadzawkach Jin\'Alai na południowym zachodzie. Trza nam wywabić ich przywódców, a Ahunae wie dokładnie, jak ty to zrobisz!$B$BIdź tam i zabijaj te trolle. Jak zabijesz dość, przyjdą ich przywódcy.$B$BJak się pokażą przy swoich totemach, ty dopilnuj, żeby zdobyć skarb Kutube\'sy, Gawanila i Chula Szalonego, mon.', 'Łowca skalpów Ahunae w Zim\'Torga poprosił cię o zdobycie skarbu Kutube\'sy, skarbu Gawanila i skarbu Chula Szalonego.', '', 'Wróć do łowcy skalpów Ahunae w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12623, 'koKR', 'Do znachora', 'Nam, Zandalarom, przydałaby się twoja pomoc, $N. Musimy położyć kres temu, co Drakkarowie robią swoim bogom!$B$BNa północnym wschodzie, na szczycie wielkich schodów prowadzących na kolejny poziom Zul\'Draku, leży Zim\'Torga. To siedziba kolejnego z posągów bogów i schronienie, którego mój lud rozpaczliwie próbuje bronić.$B$BChciałbym, żebyś się tam $gudał:udała; i $gporozmawiał:porozmawiała; ze znachorem Khufu. Ale uważaj, to miejsce jest nieustannie atakowane przez Drakkarów.', 'Porozmawiaj ze znachorem Khufu w Zim\'Torga.', '', '', '', '', '', '', 0),
(12627, 'koKR', 'Przełamanie Jin\'Alai', 'Próbowałem porozumieć się z bogami. Jednak uzdrowiciele przy Sadzawkach Jin\'Alai odprawiają rytuały, które zakłócają moje próby.$B$BKoniecznie musimy przełamać tę przeszkodę. Jeśli udasz się na południowy zachód, w okolice sadzawek, na pewno natrafisz na kotły, których używają do swojej magii.$B$BZakłóć każdy z kotłów, by przerwać rytuał, który mnie blokuje.', 'Znachor Khufu w Zim\'Torga poprosił cię o zakłócenie niebieskiego, zielonego, fioletowego i czerwonego kotła.', '', 'Wróć do znachora Khufu w Zim\'Torga w Zul\'Draku.', 'Niebieski kocioł zakłócony', 'Zielony kocioł zakłócony', 'Fioletowy kocioł zakłócony', 'Czerwony kocioł zakłócony', 0),
(12628, 'koKR', 'Rozmowa z Har\'koą', 'Bogowie przemówili, $N. Teraz wiemy, co musisz zrobić.$B$BUdaj się do Ołtarza Har\'koi na południowym wschodzie i porozmawiaj z boginią lampartów.', 'Porozmawiaj z Har\'koą przy Ołtarzu Har\'koi.', '', '', '', '', '', '', 0),
(12629, 'koKR', 'Możesz uciekać, ale się nie ukryjesz', 'Gdy Plaga weźmie kogoś na cel, nie spocznie, dopóki go nie dopadnie.$b$bJesteś $gskazany:skazana; na bezmyślną egzystencję chodzącego trupa...$b$b<Twarz Stefana wykrzywia się w okrutnym uśmiechu.>$b$b...chyba że obrócimy ich pragnienia przeciwko nim.$b$bWyjaśnię później. Muszę przygotować skomplikowaną magię, która wymaga pewnych składników.$b$bUdaj się prosto na wschód stąd, do Relikwiarza Agonii. Zabijaj plugastwa i zbieraj ślinę ghuli, którą tam znajdziesz, a potem wróć do mnie z ich szczątkami.', 'Stefan w Hebanowej Strażnicy poprosił cię, żebyś $gudał:udała; się do Relikwiarza Agonii i $gzebrał:zebrała; 5 wnętrzności gnijącego plugastwa z gnijących plugastw oraz 5 kleistych ślin ghula.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', '', '', '', '', 0),
(12630, 'koKR', 'Skopać Nassa i zebrać kłaki', 'Zanim poznasz Nassa, musisz coś wiedzieć.$b$bDawno temu dostał toksyczną dawkę zarazy i teraz jest głuchy, ślepy i prawie pozbawiony czucia.$b$bNie wszystko jednak jest złe. Jest teraz praktycznie odporny na to paskudztwo, więc idealnie nadaje się do pewnych zadań – takich jak to, które zaraz ci zlecę.$b$bW pobliżu jest wiele trolli świeżo dotkniętych przez Plagę, a my musimy zbadać, jak działa na nie zaraza. Weź Nassa i ten but. Gdy zabijesz trolla, porządnie kopnij Nassa, a będzie wiedział, że ma pobrać próbkę włosów.', 'Stefan w Hebanowej Strażnicy chce, żebyś z pomocą Nassa $gzebrał:zebrała; 10 próbek włosów wyniszczonych trolli.$b$bJeśli stracisz Nassa, wróć do Stefana, by go odzyskać.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', 'Zebrane próbki włosów', '', '', '', 0),
(12631, 'koKR', 'Swego rodzaju zaproszenie...', 'Wykonany z kości i ociekający krwią obcisły naszyjnik ma misterny, starannie przemyślany wzór.$b$bGdy na niego patrzysz, przytłacza cię złowroga obecność – zmuszająca, byś go $gzałożył:założyła;. Opierasz się tej pokusie i postanawiasz zanieść go do Hebanowej Strażnicy.$b$bJeśli ktoś potrafi to wyjaśnić, to rycerz śmierci...', 'Zanieś nieżywy obcisły naszyjnik Stefanowi w Hebanowej Strażnicy.', '', '', '', '', '', '', 0),
(12632, 'koKR', 'Najpierw moje potomstwo', 'Jestem ostatnią z bogów, których ujarzmiono, dlatego najpierw musimy spróbować uwolnić pozostałych. Spętana magią moich poskramiaczy, nie mogę dostrzec ich losu.$B$BNajpierw jednak prosiłabym cię o przysługę. Drakkarowie już obracają moją magię przeciwko mnie. Przemienili moje potomstwo w potwory.$B$BWeź jeden z moich wąsów. Zabij moje udręczone dzieci i użyj jego magii, by uwolnić je od koszmaru i przywrócić do życia.', 'Har\'koa poprosiła cię o użycie jej wąsa na zwłokach jej dzieci, by je uwolnić i wskrzesić. Gdy skończysz, wróć do niej, do Ołtarza Har\'koi.', '', 'Wróć do Har\'koi przy Ołtarzu Har\'koi w Zul\'Draku.', 'Wskrzeszeni przeklęci potomkowie Har\'koi', '', '', '', 0),
(12633, 'koKR', 'Wołanie ciemności', 'Wykonany z kości i ociekający krwią obcisły naszyjnik ma misterny, starannie przemyślany wzór.$b$bGdy na niego patrzysz, przytłacza cię złowroga obecność – zmuszająca, byś go $gzałożył:założyła;. Opierasz się tej pokusie i postanawiasz zanieść go do Hebanowej Strażnicy.$b$bJeśli ktoś potrafi to wyjaśnić, to rycerz śmierci...', 'Zanieś wijący się obcisły naszyjnik Stefanowi w Hebanowej Strażnicy.', '', '', '', '', '', '', 0),
(12635, 'koKR', 'Relikwie bogini śnieżnych lampartów', 'Słyszałem, że zamierzasz zadbać o dobro Har\'koi. Powodzenia.$B$BZastanawiam się, czy skoro będziesz w pobliżu ołtarza, nie $gzechciałbyś:zechciałabyś; odzyskać jej relikwii? Nie potrzebuję wielu, a to tylko krótka wyprawa na południowy wschód.$B$BCo ty na to?', 'Kronikarz To\'kini w Zim\'Torga chce, żebyś $godzyskał:odzyskała; 10 relikwii Har\'koi.', '', 'Wróć do kronikarza To\'kiniego w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12637, 'koKR', 'O włos', 'To mądrość albo szczęście powstrzymały cię przed założeniem tego naszyjnika, $N.$b$bTak czy inaczej, nie trafił do ciebie przypadkiem. Wziął cię na cel ktoś... albo coś...$b$bZanieś naszyjnik Krwawej Róży, o tu. Niech pokaże ci los, który omal cię nie spotkał.', 'Stefan w Hebanowej Strażnicy chce, żebyś $gzaniósł:zaniosła; nieżywy obcisły naszyjnik Krwawej Róży Daturze.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', 'Przeznaczenie naszyjnika ujawnione', '', '', '', 0),
(12638, 'koKR', 'Niewiele brakowało', 'To mądrość albo szczęście powstrzymały cię przed założeniem tego naszyjnika, $N.$b$bTak czy inaczej, nie trafił do ciebie przypadkiem. Wziął cię na cel ktoś... albo coś...$b$bZanieś naszyjnik Krwawej Róży, o tu. Niech pokaże ci los, który omal cię nie spotkał.', 'Stefan w Hebanowej Strażnicy chce, żebyś $gzaniósł:zaniosła; wijący się obcisły naszyjnik Krwawej Róży Daturze.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', 'Przeznaczenie naszyjnika ujawnione', '', '', '', 0),
(12639, 'koKR', 'Zamarznięta ziemia', 'Pojmaliśmy te żywiołaki w okolicy i mam teraz mnóstwo obrońców. Ale trzeba ogromnej mocy, by stały się dość silne, żeby stawić czoła naszym wrogom.$B$BZamarznięta ziemia w Drak\'Mabwa na północnym zachodzie ma to, czego potrzebuję, by utrzymać naszą obronę. Jeśli mam dalej to ciągnąć, potrzebuję więcej jej esencji.', 'Poskramiaczka żywiołów Dagoda w Zim\'Torga chce, żebyś $gzebrał:zebrała; 7 esencji zamarzniętej ziemi.', '', 'Wróć do poskramiaczki żywiołów Dagody w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12640, 'koKR', 'Zamykanie szczelin', 'Dagoda pośle cię na północny zachód, do Drak\'Mabwa, po więcej rzeczy dla jej obrońców, jak jeszcze nie posłała.$B$BJak już tam będziesz, Ahunae chce, ty zniszczyć szczeliny, z których te żywiołaki się wylewają. Ostatnie, czego nam trza, to żeby one nas zaatakować!$B$BTylko uważaj, więcej tej zamarzniętej ziemi przyjdzie, jak będziesz zamykać szczeliny.', 'Łowca skalpów Ahunae w Zim\'Torga poprosił cię o zamknięcie 7 szczelin żywiołów.', '', 'Wróć do łowcy skalpów Ahunae w Zim\'Torga w Zul\'Draku.', 'Zamknięte szczeliny żywiołów', '', '', '', 0),
(12642, 'koKR', 'Duch Rhunoka', 'Przeczucie mówi mi, że Rhunokowi zostało niewiele czasu.$B$BWyczuwam, że duch boga arktycznych niedźwiedzi już oddzielił się od jego osłabionego ciała. To z jego duchem musisz się porozumieć.$B$BJego ołtarz leży na północnym zachodzie, za Drak\'Mabwa.', 'Porozmawiaj z duchem Rhunoka przy Ołtarzu Rhunoka.', '', '', '', '', '', '', 0),
(12643, 'koKR', 'Promyk nadziei', 'Gdy Plaga weźmie kogoś na cel, nie spocznie, dopóki go nie dopadnie.$b$bJesteś $gskazany:skazana; na bezmyślną egzystencję chodzącego trupa...$b$b<Twarz Stefana wykrzywia się w okrutnym uśmiechu.>$b$b...chyba że obrócimy ich pragnienia przeciwko nim.$b$bWyjaśnię później. Muszę przygotować skomplikowaną magię, która wymaga pewnych składników.$b$bUdaj się prosto na wschód stąd, na ziemie pod Relikwiarzem Agonii. Zabij ghule i plugastwa, które tam znajdziesz, i wróć do mnie z ich szczątkami.', 'Stefan w Hebanowej Strażnicy poprosił cię, żebyś $gudał:udała; się do Relikwiarza Agonii i $gzebrał:zebrała; 5 wnętrzności gnijącego plugastwa z gnijących plugastw oraz 5 kleistych ślin ghula.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', '', '', '', '', 0),
(12646, 'koKR', 'Mój prorok, mój wróg', 'Mój prorok wchłonął zbyt wiele mojej mocy zbyt szybko i w efekcie sam się zabił. Skutki możesz zobaczyć w zalanym wodą kraterze na południu, w Drak\'Mabwa.$B$BMoi dawni kapłani już go wskrzesili, żeby mógł dokończyć dzieła. Przelewają w niego z powrotem moją moc i niedługo znów się przebudzi.$B$BMusisz z nim skończyć i wrócić z moim mojo, zanim będzie za późno.', 'Duch Rhunoka przy Ołtarzu Rhunoka poprosił cię o zdobycie jego mojo boga arktycznych niedźwiedzi.', '', 'Wróć do ducha Rhunoka przy Ołtarzu Rhunoka w Zul\'Draku.', '', '', '', '', 0),
(12647, 'koKR', 'Koniec cierpienia', 'Moje ciało jest już w zbyt złym stanie, $N. To tylko kwestia czasu, aż wyniosą nowego proroka, który dokończy to, co zaczął poprzedni.$B$BPrzeleję w ciebie resztkę mojej mocy. Dręczyciel w budowli ołtarza nosi kadzidło, które obudzi moje ciało i uczyni je podatnym na ciosy.$B$BUżyj kadzidła i wyświadcz mi przysługę – połóż kres mojemu cierpieniu.$B$BWybacz, jeśli będę się bronił. Nawet we mnie wola przetrwania jest silna.', 'Duch Rhunoka poprosił cię o użycie kadzidła oprawcy, by obudzić jego ciało. Następnie masz zabić Rhunoka mocą, którą przelał w ciebie jego duch.$B$BJeśli z jakiegoś powodu stracisz aurę Mojo Rhunoka, wróć do ducha Rhunoka, by ją odnowić.', '', 'Wróć do ducha Rhunoka przy Ołtarzu Rhunoka w Zul\'Draku.', '', '', '', '', 0),
(12648, 'koKR', 'Przebieranki', 'Proszę... Stworzyłem przebranie, dzięki któremu nie będzie cię można odróżnić od Plagi.$b$bDopóki przebranie działa, możesz swobodnie chodzić między nimi. Tylko morowi strażnicy przejrzą moją iluzję. Uważaj na nich!$b$bMusisz też wiedzieć, że przebranie jest niestabilne i może nagle zniknąć, więc bądź $gczujny:czujna;.$b$bWypróbujmy je. Użyj naszyjnika i odwiedź kupca Plagi tuż na wschód stąd. Wróć do mnie z butelką gorzkiej plazmy.', 'Stefan w Hebanowej Strażnicy chce, żebyś $gużył:użyła; zaczarowanego obcisłego naszyjnika, by przybrać przebranie Plagi.$b$bW postaci sługi Plagi masz kupić gorzką plazmę od Chrząstkoflaka.$b$bJeśli zgubisz zaczarowany obcisły naszyjnik, wróć po nowy do Stefana w Hebanowej Strażnicy.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', '', '', '', '', 0),
(12649, 'koKR', 'Przebierz się!', 'Proszę... Stworzyłem przebranie, dzięki któremu nie będzie cię można odróżnić od Plagi.$b$bDopóki przebranie działa, możesz swobodnie chodzić między nimi. Tylko morowi strażnicy przejrzą moją iluzję. Uważaj na nich!$b$bMusisz też wiedzieć, że przebranie jest niestabilne i może nagle zniknąć, więc bądź $gczujny:czujna;.$b$bWypróbujmy je. Użyj naszyjnika i odwiedź sprzedawcę Plagi tuż na wschód stąd. Wróć do mnie z butelką gorzkiej plazmy.', 'Stefan w Hebanowej Strażnicy chce, żebyś $gużył:użyła; zaczarowanego obcisłego naszyjnika, by przybrać przebranie Plagi.$b$bW postaci sługi Plagi masz kupić gorzką plazmę od Chrząstkoflaka.$b$bJeśli zgubisz zaczarowany obcisły naszyjnik, wróć po nowy do Stefana w Hebanowej Strażnicy.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', '', '', '', '', 0),
(12650, 'koKR', 'Grabież własnych świętości', 'W pobliżu jest jeszcze jeden ołtarz, z którego trzeba ocalić artefakty.$B$BPodobno Drakkarowie przy Ołtarzu Rhunoka na północnym zachodzie, za spękaną tundrą Drak\'Mabwa, już splądrowali własne święte miejsce.$B$B$N, byłbym wdzięczny, gdybyś $gwyrwał:wyrwała; te artefakty z ich niegodnych rąk.', 'Kronikarz To\'kini w Zim\'Torga chce, żebyś $godzyskał:odzyskała; 7 artefaktów Rhunoka.', '', 'Wróć do kronikarza To\'kiniego w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12652, 'koKR', 'Karmienie gólów', 'Chodź tu, gólu! Ta, do ciebie gadam.$b$bTera czas karmienia. Trza dać żarcie wszyskim gólom!$b$bSpecjalne żarcie tym razem! Miska flakuf i muzguf... mniam, mniam, mniam.$b$bTylko postaw miske koło góla. Dobry sposub na kumpli.$b$bMasz kumpli gólów? Ha, ha, hah!', 'Chrząstkoflak w Relikwiarzu Agonii chce, żebyś $gpostawił:postawiła; miskę flaków i mózgów obok 10 rozkładających się ghuli.', '', 'Wróć do Chrząstkoflaka w Relikwiarzu Agonii w Zul\'Draku.', 'Nakarmione rozkładające się ghule', '', '', '', 0),
(12653, 'koKR', 'Powrót do Har\'koi', 'A teraz czas, byś $gwrócił:wróciła; do bogini lampartów. Coś mi mówi, że ma wobec ciebie inne plany.$B$BPowiedz jej, że bez względu na wszystko jesteśmy wieczni.', 'Porozmawiaj z Har\'koą przy Ołtarzu Har\'koi.', '', '', '', '', '', '', 0),
(12655, 'koKR', 'Błogosławieństwo Zim\'Rhuka', 'Jest jeszcze jeden bóg Zul\'Draku, o którym zapomniano.$B$BPosąg Zim\'Rhuka stoi prosto na północy. Zim\'Rhuk, zwany „Mądrym”, słynie też z tego, że zazdrośnie strzeże swojej domeny. Utrzymuje strażników, którzy surowo rozprawiają się z każdym, komu nie starczy sprytu, by się obok nich prześlizgnąć.$B$BUnikaj strażników i złóż ofiary Drakkarów Zim\'Rhukowi, by zyskać jego błogosławieństwo.', 'Znachor Khufu chce, żebyś $gzłożył:złożyła; 10 ofiar Drakkarów przed posągiem Zim\'Rhuka.', '', 'Dostarcz ofiary Drakkarów Zim\'Rhukowi w Zim\'Rhuk w Zul\'Draku.', '', '', '', '', 0),
(12656, 'koKR', 'Błogosławieństwo Zim\'Rhuka', '', '', '', 'Wróć do Zim\'Rhuka w Zul\'Draku.', '', '', '', '', 0),
(12659, 'koKR', 'Skalpy!', 'Ahunae myśli, że czas trochę poskalpować, mon!$B$BTrolle z Heb\'Drakkar na północnym wschodzie nadadzą się w sam raz. Z tymi ich wymyślnymi nietoperzami i atakami na nas – same się proszą!$B$BAhunae nawet da ci własny nóż, co by robota była porządnie zrobiona.', 'Łowca skalpów Ahunae w Zim\'Torga chce, żebyś nożem Ahunae $goskalpował:oskalpowała; 10 trolli z Heb\'Drakkar.$B$BŁowca skalpów przypomina, że najpierw trzeba je ograbić.', '', 'Wróć do łowcy skalpów Ahunae w Zim\'Torga w Zul\'Draku.', 'Oskalpowane trolle z Heb\'Drakkar', '', '', '', 0),
(12661, 'koKR', 'Infiltracja Voltarusa', 'Pewnie już się $gdomyśliłeś:domyśliłaś; szczegółów mojego planu.$b$bObrócimy zainteresowanie Plagi tobą przeciwko niej. Wejdziesz między nich pod przykrywką. Wiem, że to prawdopodobnie wyrok śmierci, ale jeśli nic nie zrobimy, twoja śmierć jest pewna.$b$bUdaj się na północny wschód, do Relikwiarza Bólu, i stań na platformie w przebraniu. Gdy znajdziesz się w Voltarusie, musisz zdobyć zaufanie dowódcy Plagi.$b$bKiedy wykonasz misję, zadmij w ten róg, a przylecę do ciebie po raport.', 'Stefan chce, żebyś za pomocą zaczarowanego obcisłego naszyjnika $gdostał:dostała; się do Voltarusa i $gwykonał:wykonała; wszystko, o co poprosi cię tamtejszy przywódca Plagi.$b$bJeśli zgubisz zaczarowany obcisły naszyjnik, wróć po nowy do Stefana w Hebanowej Strażnicy.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', 'Zadanie nadrządcy Drakuru wykonane', '', '', '', 0),
(12662, 'koKR', 'Strącenie Heb\'Jina', '<Dagoda spogląda na Ahunae i wzdycha.>$B$BChcesz naprawdę rozprawić się z Heb\'Drakkar? Zbieranie skalpów nic nie da. Musisz zlikwidować ich przywódcę, Heb\'Jina.$B$BKłopot w tym, że siedzi na górze, w nietoperzarni, i podjudza swoje wojska.$B$BUderz w jego bęben, a gwarantuję, że sfrunie na dół. Wtedy go zabij.$B$BWeź tę sieć, którą zdobyliśmy od jednego z jego łowców głów. Użyj jej, by złapać jego nietoperza, gdy wyląduje. Wtedy nie trzeba będzie walczyć z oboma naraz.$B', 'Poskramiaczka żywiołów Dagoda w Zim\'Torga chce, żebyś $gzabił:zabiła; Heb\'Jina.', '', 'Wróć do poskramiaczki żywiołów Dagody w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12663, 'koKR', 'Ponowne spotkanie', '$n!$b$b$GMusiałeś:Musiałaś; dostać mój prezent! Obróć się, mon, niech ci się dobrze przyjrzę... Ach, jestem z ciebie dumny.$b$bDaleką drogę przeszliśmy, ty i ja, a teraz razem służymy Królowi Liszowi.$b$bTrzymaj się mnie, a wielkie rzeczy nadejdą, mon. Wielkie rzeczy... ale najpierw musisz nadrobić zaległości. Tyle się wydarzyło, odkąd cię ostatnio widziałem.$b$bIdź do Juchowora, niech cię oprowadzi po Zul\'Draku. Słuchaj mnie, a powiem ci wszystko, co ci trza wiedzieć.', 'Drakuru w Voltarusie chce, żebyś $gporozmawiał:porozmawiała; z Juchoworem i $gwybrał:wybrała; się na wycieczkę po Zul\'Draku.', '', 'Wróć do nadrządcy Drakuru w Voltarusie w Zul\'Draku.', 'Wycieczka po Zul\'Draku zakończona', '', '', '', 0),
(12664, 'koKR', 'Mroczny horyzont', 'Ach, kolejna dusza, co odpowiada na wezwanie Króla Lisza.$b$b<Drakuru cię obwąchuje.>$b$b$GŚwieżo przemieniony:Świeżo przemieniona; przez Plagę, co? Wciąż cuchniesz żywymi!$b$bDługa jest kolejka tych, co szukają błogosławieństwa Króla Lisza. Musisz wybić się ponad tłum i udowodnić, że jesteś $ggodny:godna; władania prawdziwą mocą.$b$bPatrząc z góry na Zul\'Drak, wyczułem w tobie potencjał. Kazałem ci wysłać... zaproszenie.$b$bReszta zależy od ciebie...$b$bIdź do Juchowora, niech cię oprowadzi po Zul\'Draku. Jest dużo do zrobienia, jeśli masz być coś dla mnie $gwart:warta;.', 'Drakuru w Voltarusie chce, żebyś $gporozmawiał:porozmawiała; z Juchoworem i $gwybrał:wybrała; się na wycieczkę po Zul\'Draku.', '', 'Wróć do nadrządcy Drakuru w Voltarusie w Zul\'Draku.', 'Wycieczka po Zul\'Draku zakończona', '', '', '', 0),
(12665, 'koKR', 'Wyczuwam niepokój', 'Coś jest nie tak z Quetz\'lun, boginią powietrznych węży. Nie potrafię wyczuć, co dokładnie, ale wiem, że jej ołtarz opanowały potężne stwory.$B$BPoślę cię tam na grzbiecie jednego z moich dzieci, które $guratowałeś:uratowałaś;. Razem ruszycie szybko i ukradkiem, by odkryć, co stało się z Quetz\'lun.$B$BMoje dziecko bezpiecznie odprowadzi cię z powrotem do mnie. Tylko miej oczy szeroko otwarte.$B$BGdy będziesz $ggotowy:gotowa;, poproś, a przywołam dla ciebie jedno z moich kociąt.', 'Har\'koa poprosiła cię o ustalenie, co się stało z Quetz\'lun. Porozmawiaj z nią, by po cichu wjechać na grzbiecie jednego z jej dzieci do Ołtarza Quetz\'lun.$B$BGdy to zrobisz, wróć do niej, do Ołtarza Har\'koi.', 'Los Quetz\'lun odkryty.', 'Wróć do Har\'koi przy Ołtarzu Har\'koi w Zul\'Draku.', '', '', '', '', 0),
(12666, 'koKR', 'Przygotowania do zaświatów', 'Quetz\'lun może i nie żyje, ale wciąż czuję, jak jej duch błąka się w zaświatach przy ołtarzu. Musimy znaleźć sposób, by cię do niej dostarczyć.$B$BNa szczęście tak się składa, że mam pod ręką zapas byłych wyznawców, którym nie są już potrzebne ich święte ozdoby. Zarówno moi poskramiacze, jak i pazury pewnie wciąż je noszą.$B$BPrzynieś mi te ozdoby, a zaczerpnę z nich energię, by umożliwić ci przejście do koszmaru Quetz\'lun w zaświatach.', 'Har\'koa chce, żebyś $gzebrał:zebrała; 8 świętych ozdób. Dostarcz je jej do Ołtarza Har\'koi.', '', 'Wróć do Har\'koi przy Ołtarzu Har\'koi w Zul\'Draku.', '', '', '', '', 0),
(12667, 'koKR', 'Odszukaj boginię powietrznych węży', 'Masz wszystko, czego trzeba, ale nie jestem pewna, czy jesteś $ggotowy:gotowa; na to, co nadejdzie.$B$BGdy wrócisz w okolice ołtarza Quetz\'lun, wkroczysz do królestwa umarłych. Z tego, co czuję, nie będzie to przyjemne.$B$BStaraj się nie rozpraszać tym, co tam zobaczysz. Po prostu idź do budowli ołtarza i odszukaj ducha Quetz\'lun.', 'Odszukaj ducha Quetz\'lun przy Ołtarzu Quetz\'lun.', '', '', '', '', '', '', 0),
(12668, 'koKR', 'Fundament zemsty', 'Szykuję coś szczególnego dla moich ulubionych arcykapłanów. Ale najpierw udowodnisz swoją wartość, kładąc fundament pod moją zemstę.$B$BWciąż chcesz żyć, prawda?$B$BJak widzisz, moi wyznawcy cieszą się pobytem tutaj, ale teraz nadszedł czas, by ostatecznie odpokutowali.$B$BWyświadcz mi drobną przysługę, $N. Zwab ich do moich studni dusz, a potem zakończ ich istnienie.$B$BSmakują tak wybornie, a ich ofiara nie pójdzie na marne, zapewniam cię.', 'Duch Quetz\'lun zlecił ci zabicie 12 trolli – wyznawców Quetz\'lun lub berserkerów naznaczonych przez węża – w pobliżu jej studni dusz.$B$BDopiero gdy tego dokonasz, wróć do niej, do Ołtarza Quetz\'lun.', '', 'Wróć do ducha Quetz\'lun przy Ołtarzu Quetz\'lun w Zul\'Draku.', 'Trolle zabite przy studni dusz', '', '', '', 0),
(12669, 'koKR', 'Jak dotąd źle', 'Wszystko, o czym $gmeldowałeś:meldowałaś;, zgadza się z tym, co wiemy. Poznanie Drakuru i zdobycie jego zaufania przygotuje grunt pod twoje przyszłe misje.$b$bWróć do niego i rób, co każe. Rób, co musisz, by wyglądać na $gszczerego:szczerą;, $n. Wiele zależy od tego, jak się spiszesz.$b$bTym razem dokładam ci dodatkowe zadanie: gdy będziesz w terenie, wlej ten dodatek do ich kotłów z zarazą. Powinien zneutralizować czynnik przemiany i sprawić, że cała partia będzie bezużyteczna.', 'Stefan w Hebanowej Strażnicy chce, żebyś $gwrócił:wróciła; do Drakuru i $gwykonał:wykonała; wszystkie jego zadania.$b$bW Relikwiarzu Bólu masz użyć dodatku rozcieńczającego na 5 kotłach z zarazą.$b$bJeśli zgubisz zaczarowany obcisły naszyjnik, wróć po nowy do Stefana w Hebanowej Strażnicy.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', 'Zadanie Drakuru wykonane', 'Rozcieńczone kotły z zarazą', '', '', 0),
(12672, 'koKR', 'Przygotowanie sceny', 'Dam ci szansę na dalsze istnienie.$B$BWokół ołtarza leżą rozrzucone fragmenty mocy, która zasiliła moją klątwę. Życzę sobie, byś $gzebrał:zebrała; dla mnie kilka z nich. Nie tak wiele, by klątwa została zdjęta, ale tyle, bym mogła kiedyś ich użyć, by zemścić się na moim proroku.$B$BIdź, owadzie. Biegnij i wykonaj mój rozkaz, zanim się rozmyślę i nie pozwolę ci żyć.', 'Duch Quetz\'lun zażądał, żebyś $gzebrał:zebrała; 10 fragmentów mocy zaświatów. Wróć do niej, do Ołtarza Quetz\'lun, dopiero gdy to zrobisz.', '', 'Wróć do ducha Quetz\'lun przy Ołtarzu Quetz\'lun w Zul\'Draku.', '', '', '', '', 0),
(12673, 'koKR', 'Z góry na dół', 'Jeśli masz być kiedyś $ggodny:godna; darów Króla Lisza, musisz się nauczyć być wielkim przywódcą – takim, co budzi szacunek!$b$bMam zadanie, co wyszlifuje twoje umiejętności dowodzenia, mon...$b$bNiektóre moje sługi są wyszkolone, żeby zbierać kryształy zarazy z ziemi na dole, ale są leniwe i powolne. Ty będziesz nimi dowodzić, mon.$b$bWeź to berło i naucz je, jak się robi robotę. Jak będą pod twoją kontrolą, każ im zbierać te kryształy!', 'Nadrządca Drakuru w Voltarusie chce, żebyś $gużył:użyła; berła sugestii na fantomach zarazy, a następnie $gkazał:kazała; im zebrać 7 kryształów zarazy.', '', 'Wróć do nadrządcy Drakuru w Voltarusie w Zul\'Draku.', 'Zebrane kryształy zarazy', '', '', '', 0),
(12674, 'koKR', 'Piekielna furia', 'Nadszedł czas, byś $gukarał:ukarała; moich trzech arcykapłanów: Mu\'funu, Tua-Tuę i Hawinniego. Znajdziesz ich rozproszonych wokół ołtarza.$B$BWeź tę klątwopałkę. Nasyciłam ją swoim gniewem i oburzeniem. Jestem pewna, że okaże się skuteczna.$B$BPo prostu jej użyj, a potem ich zniszcz. Klątwa zajmie się resztą.$B$B<Quetz\'lun szczerzy zęby w uśmiechu.>$B$BUda ci się, a może cię wypuszczę. Zawiedziesz – zginiesz.', 'Duch Quetz\'lun przy Ołtarzu Quetz\'lun chce, żebyś $gużył:użyła; klątwopałki Quetz\'lun na arcykapłanie Mu\'funu, arcykapłance Tua-Tui i arcykapłanie Hawinnim. Potem masz ich zabić.', '', 'Wróć do ducha Quetz\'lun przy Ołtarzu Quetz\'lun w Zul\'Draku.', 'Arcykapłan Mu\'funu przeklęty w chwili śmierci', 'Arcykapłanka Tua-Tua przeklęta w chwili śmierci', 'Arcykapłan Hawinni przeklęty w chwili śmierci', '', 0),
(12675, 'koKR', 'Ostatnia rzecz', 'Do dokonania ostatecznej zemsty na moim proroku potrzebna jest jeszcze jedna rzecz. Fragmenty mocy, które $gzebrałeś:zebrałaś;, muszą zostać nasycone cząstką ducha żywego boga. Musisz błagać Har\'koę o cząstkę jej ducha.$B$BGdy to zrobisz i tu wrócisz, nie trafisz do zaświatów. Wrócisz za to do fizycznego świata mojego ołtarza. Moje dzieci i strażnicy przestaną cię atakować i będziesz $gmógł:mogła; dotrzeć do mojego proroka, nie martwiąc się o nich.', 'Dostarcz fragmenty mocy zaświatów Har\'koi i błagaj ją o cząstkę jej ducha. Nadal znajdziesz ją przy Ołtarzu Har\'koi.', '', 'Wróć do Har\'koi przy Ołtarzu Har\'koi w Zul\'Draku.', '', '', '', '', 0),
(12676, 'koKR', 'Sabotaż', 'Podczas gdy my próbujemy odkryć przeznaczenie tych kryształów, ty musisz wrócić do Voltarusa i wykonywać polecenia Drakuru.$b$bKażde zadanie, które pomyślnie wykonasz, przybliża cię do niego, a nas – do poznania jego zamysłów.$b$bSkoro już tam będziesz, mam dla ciebie kolejną misję. Wozy Plagi Drakuru stanowią poważne zagrożenie. Trzeba je zniszczyć.$b$bDostań się do wozów i uaktywnij te ładunki. Gdy je podłożysz, uciekaj! Wybuch cię zdemaskuje, jeśli będziesz zbyt blisko.', 'Stefan w Hebanowej Strażnicy chce, żebyś $gwykonał:wykonała; kolejne zadanie dla Drakuru.$b$bPonadto masz użyć ładunków wybuchowych na 5 wozach Plagi w Relikwiarzu Bólu.$b$bJeśli zgubisz zaczarowany obcisły naszyjnik, wróć po nowy do Stefana w Hebanowej Strażnicy.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', 'Zniszczone wozy Plagi', 'Zadanie Drakuru wykonane', 'Poznaj sekret Drakuru', '', 0),
(12677, 'koKR', 'Materiały niebezpieczne', 'Kryształy zarazy?! Co ten łajdak Drakuru knuje? Najwyraźniej pracuje nad czymś poważnym.$b$bWykonuj dalej jego polecenia, a może gdy lepiej cię pozna, zdradzi swoje plany. Tymczasem musimy przyjrzeć się tym kryształom.$b$bGdy będziesz w Voltarusie, spróbuj zdobyć próbki zebranych kryształów, kiedy nikt nie będzie patrzył.$b$bUważaj! Dotykanie tych kryształów może sprawić, że przebranie zawiedzie.', 'Stefan w Hebanowej Strażnicy chce, żebyś $gudał:udała; się do Voltarusa i $gwykonał:wykonała; wszystkie zadania, jakie ma dla ciebie Drakuru. Przy okazji masz ukraść 5 zebranych kryształów zarazy.$b$bJeśli zgubisz zaczarowany obcisły naszyjnik, wróć po nowy do Stefana w Hebanowej Strażnicy.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', 'Zadanie Drakuru wykonane', '', '', '', 0),
(12684, 'koKR', 'Krew martwego boga', 'Mam\'toth, bóg mamutów, wolał zniszczyć samego siebie – i dużą część swojej świątyni – niż pozwolić swoim trollom przejąć jego moc.$B$BJeśli mam poświęcić cząstkę mojego ducha, będę potrzebować czegoś, co mnie wzmocni.$B$BMam\'toth pozostawił po sobie ogromny krater na północnym wschodzie, tuż na północ od Ołtarza Quetz\'lun. W kraterze wciąż żyje jego krew.$B$BPrzynieś mi ją.', 'Har\'koa poprosiła cię o zebranie 7 porcji krwi Mam\'totha. Zanieś je jej do Ołtarza Har\'koi.', '', 'Wróć do Har\'koi przy Ołtarzu Har\'koi w Zul\'Draku.', '', '', '', '', 0),
(12685, 'koKR', 'Co zasiejesz, to zbierzesz', 'Oto do czego doszło... do zemsty.$B$B<Har\'koa wzdycha.>$B$BWeź ten zestaw rytualny i odpraw rytuał przy zwłokach Quetz\'lun na jej ołtarzu. Jeśli wszystko pójdzie dobrze, jej duch powinien zostać wciągnięty do świata materialnego, gdzie odbierze prorokowi swoją moc.$B$BReszta będzie zależeć od ciebie, $N. Musisz zabić proroka, gdy będzie wyczerpany.', 'Zabij wyczerpanego proroka Quetz\'lun, a następnie powiadom znachora Khufu w Zim\'Torga.', '', 'Wróć do znachora Khufu w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12686, 'koKR', 'Zero tolerancji', 'Ignorancja! To nie do zniesienia, mon! Cała moja partia zarazy do niczego!$b$bTen kundel, Darmuk! On miał pilnować zarazy. Zawiódł mnie, mon!$b$bTo dobra lekcja dla ciebie, $n. Porażka jest jak choroba, co się szerzy. Trza ją złapać i zabić wcześnie, zanim ona zabije ciebie!$b$bWeź to berło. Ono wzmacnia moje trolle przemienione przez Plagę. Użyj ich, żeby zabić Darmuka. On czai się na dole, zaraz na południu.$b$bNiech to będzie przykład dla wszystkich, mon. Nie zawodzić Drakuru!', 'Drakuru w Voltarusie chce, żebyś $gudał:udała; się do Relikwiarza Bólu i $gużył:użyła; berła wzmocnienia na słudze Drakuru. Następnie masz pokonać Darmuka za pomocą jego zdolności.', '', 'Wróć do nadrządcy Drakuru w Voltarusie w Zul\'Draku.', 'Darmuk zabity', '', '', '', 0),
(12690, 'koKR', 'Paliwo dla ognia', 'Czas, żebyśmy zaczęli marsz na Gundrak, mon. Czas, żebym cię spuścił na te trolle!$b$bPrzebili się przez nasz mur i postawili całą armię tuż na północ od nas.$b$bHahaha!$b$bOni będą paliwem dla ognia, mon! Weźmiemy wodzów, a resztę zabijemy! To wszystko część mojego wielkiego planu...$b$bWeź to berło i idź dowodzić moimi plugastwami. Zaprowadź je do armii Drakkarów i zabij wszystkich! Jak przyjdą wodzowie, mój pupil Łupkoskrzydły ich porwie i przyniesie tutaj, do mnie.', 'Drakuru w Voltarusie chce, żebyś $gużył:użyła; berła dowodzenia na wzdętych plugastwach, a następnie za pomocą ich zdolności $gzabił:zabiła; 60 miażdżycieli czaszek Drakkarów w Lodowatym Wyłomie i $gwywabił:wywabiła; 3 wodzów Drakkarów.$b$bWodzowie pojawią się, gdy zginie dość miażdżycieli czaszek.', '', 'Wróć do nadrządcy Drakuru w Voltarusie w Zul\'Draku.', 'Zabici miażdżyciele czaszek Drakkarów', 'Wywabiony wódz Drakkarów', '', '', 0),
(12707, 'koKR', 'Wełniasta sprawiedliwość', 'Ahunae słyszał o twojej wyprawie do Krateru Mam\'totha, mon. Dzieci Mam\'totha są rozwścieczone i wołają o sprawiedliwość!$B$BIdź aleją na północny wschód, po schodach na kolejny poziom Zul\'Draku. Po prawej znajdziesz to, co zostało z Ołtarza Mam\'totha.$B$BJak tam dojdziesz, błyśnij tym medalionem Mam\'totha przed oczami jednego z rozwścieczonych mamutów. Uspokoi się na chwilę, a ty wskoczysz mu na grzbiet.$B$BJeździj na nim i tratuj wszystkich uczniów Mam\'totha, co znajdziesz!', 'Łowca skalpów Ahunae w Zim\'Torga chce, żebyś za pomocą medalionu Mam\'totha $guspokoił:uspokoiła; rozwścieczonego mamuta i $gdosiadł:dosiadła; go. Następnie masz stratować na śmierć 12 uczniów Mam\'totha.', '', 'Wróć do łowcy skalpów Ahunae w Zim\'Torga w Zul\'Draku.', 'Uczniowie Mam\'totha stratowani na śmierć', '', '', '', 0),
(12708, 'koKR', 'Zaczarowani wojownicy tiki', 'Wiem, że wybierasz się do Warowni Zol\'Maz na północnym wschodzie, $N. Skoro już tam będziesz, musisz rozprawić się ze specjalnymi strażnikami wodza wojennego.$B$BTak zwani zaczarowani wojownicy tiki stanowią bardzo realne zagrożenie. Gdyby Drakkarowie zaczęli ich produkować masowo, szybko by nas zalali.$B$BPokażmy im, ty i ja, że nie warto zadawać sobie trudu, by ich tworzyć, dobrze?', 'Poskramiaczka żywiołów Dagoda w Zim\'Torga poprosiła cię o zniszczenie 12 zaczarowanych wojowników tiki.', '', 'Wróć do poskramiaczki żywiołów Dagody w Zim\'Torga w Zul\'Draku.', 'Zniszczeni zaczarowani wojownicy tiki', '', '', '', 0),
(12709, 'koKR', 'Przeklęte skrytki', 'Wybacz, $N. Dano mi do zrozumienia, że możesz się wybierać na północny wschód, do Warowni Zol\'Maz. Taka wyprawa to dla nas świetna okazja, by dokończyć zbieranie dóbr Drakkarów.$B$BJak się dowiedziałem, wódz wojenny Drakkarów to straszny paranoik. Kazał obłożyć wszystkie swoje skrytki w warowni złowrogą klątwą. Plotka głosi, że jego wojownicy tiki noszą przy sobie lekarstwo, ale kto to wie?$B$BJeśli znajdziesz czas, żeby zdobyć trochę tych dóbr, będę ci niezmiernie wdzięczny.', 'Kronikarz To\'kini w Zim\'Torga poprosił cię o zdobycie 12 skrytek Warowni Zol\'Maz.', '', 'Wróć do kronikarza To\'kiniego w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12710, 'koKR', 'Wyjawienie', 'Dobrze ci idzie, $n.$b$bUdowadniasz, że mam oko do talentów! Teraz widzisz, czemu Król Lisz dał mi swoje błogosławieństwo...$b$bNadszedł czas, bym wyjawił ci mój wielki plan, mon.$b$bTeraz zobaczysz, jak przetoczymy się przez chmary Drakkarów, by zająć należne nam miejsce w wielkim pałacu Gundraku.$b$bWeź to berło, mon. To znak mojego zaufania do ciebie. Dzięki niemu dostaniesz się do mojej górnej komnaty i na własne oczy zobaczysz naszą tajną broń.', 'Drakuru w Voltarusie chce, żebyś $gprzeniósł:przeniosła; się teleporterem do jego górnej komnaty.', '', 'Wróć do nadrządcy Drakuru w Voltarusie w Zul\'Draku.', 'Górna komnata Drakuru zbadana', '', '', '', 0),
(12712, 'koKR', 'Klucz wodza Zol\'Maza', '$N, potrzebujemy klucza, by rozpiąć łańcuchy boga nosorożców, Akaliego. Już teraz szykują go na rzeź.$B$BKlucz ma wódz wojenny Drakkarów, Zol\'Maz. Słysząc o twoich wyczynach, zaszył się wraz z rodziną w swojej warowni, na szczycie schodów na północnym wschodzie.$B$BWódz jest silny i będziesz potrzebować pomocy. Jeśli połączysz tiki, miecz i inkantację członków jego rodziny, będziesz $gmógł:mogła; przywołać taką pomoc, gdy wyzwiesz go przed bramą jego domu.', 'Har\'koa w Zim\'Torga poprosiła cię o zdobycie klucza wodza Zol\'Maza.', '', 'Wróć do Har\'koi w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12713, 'koKR', 'Zdrada', 'Czas skończyć tę maskaradę, $n.$b$bJakkolwiek cenne były twoje informacje, musimy obalić Drakuru i położyć kres jego przedsięwzięciu, zanim jego pomioty zostaną wypuszczone.$b$bPrzerobiliśmy twoje berło do tego zadania. Gdy nadejdzie właściwa chwila, użyjesz go na trollach o skażonej krwi Drakuru i zwrócisz je przeciwko niemu. To twoja jedyna szansa, by go pokonać.$b$bWalcz dzielnie.', 'Stefan w Hebanowej Strażnicy chce, żebyś $gpokonał:pokonała; Drakuru.$b$bJeśli zgubisz zaczarowany obcisły naszyjnik, wróć do Stefana w Hebanowej Strażnicy po nowy.', '', 'Wróć do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', 'Pokonany Nadrządca Drakuru', '', '', '', 0),
(12721, 'koKR', 'Amok', '$N, nie ma już czasu. Weź klucz i użyj go, by uwolnić Akaliego.$B$BTrzymają go na dziedzińcu przed Gundrakiem, stolicą Zul\'Draku. Łańcuchy Akaliego przymocowano do czterech kotwic. Musisz otworzyć każdą z nich, by uwolnić boga nosorożców.$B$BW Gundraku roi się od lodowych trolli. Myślę jednak, że jeśli zachowasz ostrożność, zdołasz się tam wśliznąć bez większego ryzyka.$B$BGdy skończysz, powiadom znachora.', 'Har\'koa w Zim\'Torga poprosiła cię o uwolnienie Akaliego, a następnie o powiadomienie znachora Khufu w Zim\'Torga.', 'Akali uwolniony z łańcuchów.', 'Wróć do znachora Khufu w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12729, 'koKR', 'Bogowie przemówili', 'Bogowie przemówili i musimy posłuchać ich mądrości.$B$BZbierz przy sobie przyjaciół, $N. Zabierz ich na północ, do Zim\'Rhuk, i niszczcie tamtejszych strażników, dopóki nie oddadzą nieskazitelnego serca. Zabierz ich na wschód, do Ołtarza Quetz\'lun, i nękajcie opiekunów ołtarza, aż odzyskasz ich porywistą esencję.$B$BDostarcz jedno i drugie Har\'koi, a ona połączy je w coś, co zmusi proroka nieżyjącego Akaliego do pojawienia się.', 'Dostarcz nieskazitelne serce strażnika i porywistą esencję opiekuna Har\'koi w Zim\'Torga.', '', 'Wróć do Har\'koi w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12730, 'koKR', 'Zgromadzenie w Zol\'Heb', 'Ty i twoi przyjaciele musicie zanieść ten instrument zgromadzenia – przywołania – do Zol\'Heb, tuż na południe od Gundraku.$B$BZnajdziesz tam krąg mocy. Użyj zgromadzenia, by zmusić proroka Akaliego do pojawienia się.$B$BSerce mi się kraje, $N. Wiele razem przeszliśmy, a ty $gzrobiłeś:zrobiłaś; wszystko, co w twojej mocy, by ocalić nie tylko moje życie, ale i życie innych bogów, których zniszczyli Drakkarowie.$B$BLecz obawiam się, że tym razem możemy się już nie spotkać aż do życia pozagrobowego.', 'Har\'koa w Zim\'Torga poprosiła cię o zabicie proroka Akaliego.', '', 'Wróć do Har\'koi w Zim\'Torga w Zul\'Draku.', '', '', '', '', 0),
(12740, 'koKR', 'Spadochrony dla Krucjaty Argentu', 'Te podniebne postrachy wybijają moich ludzi! Śmierć od upadku to straszny koniec.$B$B$N, musisz dostarczyć im te spadochrony! Wtedy przynajmniej będą mieli szansę przeżyć.', 'Dowódca Falstaav w Reducie Argentu poprosił cię o wyposażenie w spadochrony 10 krzyżowców Argentu lub tarczowników Argentu na dziedzińcu.', '', 'Wróć do dowódcy Falstaava w Reducie Argentu w Zul\'Draku.', 'Żołnierze Argentu wyposażeni w spadochron', '', '', '', 0),
(12780, 'koKR', 'PRZESTARZAŁE>>Wróg naszego wroga', 'Choć współpraca z rycerzami śmierci budzi w nas niesmak, nie możemy sobie tutaj pozwolić na wybrzydzanie w doborze sojuszników.$b$bJesteśmy wciśnięci między Plagę a dzikich Drakkarów, którzy niczego bardziej nie pragną, niż zniszczyć nas, by dobrać się do siebie nawzajem.$b$bUdaj się na zachód, do Hebanowej Strażnicy. Porozmawiaj ze Stefanem i sprawdź, czy możesz mu się na coś przydać.', 'Sierżant Riannah w Wyłomie Światłości chce, żebyś $gporozmawiał:porozmawiała; ze Stefanem w Hebanowej Strażnicy i $gzaoferował:zaoferowała; mu pomoc.', '', '', '', '', '', '', 0),
(12792, 'koKR', 'Najpierw najważniejsze', 'Słuchaj, $r!$b$bCały ten region to jeden wielki kryzys. Gdziekolwiek spojrzysz, znajdziesz kogoś, komu przyda się twoja pomoc.$b$b<Kunz patrzy ci prosto w oczy.>$b$bAle nikt nie potrzebuje jej teraz bardziej niż Riannah. Plaga wdarła się między nas, odcinając ją i jej ludzi.$b$bWyłom Światłości, gdzie bronią się jej oddziały, leży tuż na południowy zachód stąd.', 'Dowódca Kunz w Reducie Argentu chce, żebyś $gzgłosił:zgłosiła; się do sierżant Riannah w Wyłomie Światłości.', '', '', '', '', '', '', 0),
(12793, 'koKR', 'Dym na horyzoncie', 'Słyszysz to, $r?$b$bZgiełk bitwy daleko na zachodzie dociera aż tutaj, nawet przez hałas naszej własnej walki.$b$bPlaga grozi przełamaniem linii tych, którzy nazywają siebie Krucjatą Argentu. Zapobieżenie temu jest równie pilne jak wszystko inne w tym regionie.$b$bUdaj się do Wyłomu Światłości i przyłącz się do ich walki. Porozmawiaj z Maaką, a zapewni ci bezpieczny przejazd.', 'Khufu w Zim\'Torga chce, żebyś $gudał:udała; się do Wyłomu Światłości i $gzgłosił:zgłosiła; się tam do sierżant Riannah.$b$bMaaka zapewni ci transport.', '', '', '', '', '', '', 0),
(12795, 'koKR', 'Stawić czoła', 'Przed chwilą zauważyłam flarę sygnałową nad linią drzew na wschodzie.$b$bTo może oznaczać tylko jedno: krzyżowcom w Reducie Argentu nie idzie najlepiej.$b$bJa nie mogę opuścić tu posterunku, $r, ale ty możesz. Gdy znajdziesz czas, udaj się do dowódcy Falstaava i sprawdź, czy możesz jakoś ulżyć im w ciężarze.', 'Krwawa Róża Datura w Hebanowej Strażnicy chce, żebyś $gporozmawiał:porozmawiała; z dowódcą Falstaavem w Reducie Argentu.', '', '', '', '', '', '', 0),
(12799, 'koKR', 'Wysysanie duchów', '„Ciesz się, że przyjeżdża” – mówili. „Polubisz jego towarzystwo” – mówili...$b$bCóż, i tak nie miałem nic do gadania. Finklestein to najlepszy alchemik Krucjaty. Pewnie powinienem czuć się zaszczycony, że to mój posterunek wybrał na swój warsztat. Ale od kiedy przybył, zostałem zdegradowany do zbierania rozmaitych składników alchemicznych.$b$bSłuchaj, $r, może byś mi $gpomógł:pomogła;? Tuż na południe stąd są sadzawki nawiedzane przez duchy pradawnych trolli. Zbierz dla mnie ich ektoplazmę.', 'Kapitan Arnath w Heb\'Valok chce, żebyś $gzebrał:zebrała; 5 pradawnych ektoplazm od zagubionych duchów Drakkarów przy Sadzawkach Zha\'Jin.', '', 'Wróć do kapitana Arnatha w Heb\'Valok w Zul\'Draku.', '', '', '', '', 0),
(12857, 'koKR', 'Poszukiwana: płetwa Wściekłogrzywego', 'Ogłasza wódz Wściekły Pazur:$B$BWierny lew morski wodza Wściekłego Pazura, Wściekłogrzywy, gryźć rękę, co go karmić. Wściekły Pazur mówić, Wściekłogrzywy już nie dobry przez złe trolle Drakuru. Wódz Wściekły Pazur bardzo smutny prosić, żeby Wściekłogrzywy zabity i płetwa Wściekłogrzywego oddana wodzowi na dowód.$B$BWściekłogrzywego znaleźć na południowym wschodzie, nad Jeziorem Wściekłych Pazurów.$B$BWódz Wściekły Pazur przeprasza za brzydkie pisanie. Pierwszy raz używać jedno z tych rzeczy; poza tym wódz Wściekły Pazur to wolvar, nie człowiek.$B', 'Zdobądź płetwę Wściekłogrzywego i zanieś ją wodzowi Wściekłemu Pazurowi w Wyłomie Światłości w Zul\'Draku.', '', 'Wróć do wodza Wściekłego Pazura w Wyłomie Światłości w Zul\'Draku.', '', '', '', '', 0),
(12859, 'koKR', 'Z ostatniej chwili: ogień nadal gorący!', 'Trolle atakować Norę Wściekłych Pazurów i wykopać Wściekłe Pazury! Jest gorzej. Trolle teraz palić wioskę! To bardzo źle. Wódz kazać najlepszy szaman Wściekłych Pazurów, Moky, badać ogień. Wyniki bardzo zaskakujące! Ogień nadal gorący i może palić rzeczy.$B$BPomożesz Wściekłym Pazurom i zgasisz ogień? Moky mieć dla ciebie specjalna gaśnica Wściekłych Pazurów. Użyj specjalna gaśnica i zgaś ogień w Norze Wściekłych Pazurów na południowym wschodzie. Czasem trzeba dużo psikać, żeby zgasić ogień, ale w gaśnicy zawsze jest woda! Magia Wściekłych Pazurów silna!', 'Starszy szaman Moky w Wyłomie Światłości w Zul\'Draku chce, żebyś $gużył:użyła; gaśnicy Wściekłych Pazurów, by ugasić 15 pożarów chat w Norze Wściekłych Pazurów.$B', '', 'Wróć do starszego szamana Moky\'ego w Wyłomie Światłości w Zul\'Draku.', 'Pożary chat ugaszone', '', '', '', 0),
(12861, 'koKR', 'Trolle całkiem oszaleć!', 'Drakuru... Wiesz, kto to za troll? Ja myśleć, że złe trolle słuchać trolla Drakuru. One nazywać siebie trolle Drakuru – po tym ja wiedzieć. Teraz widzisz, czemu ja wodzem Wściekłych Pazurów. Najmądrzejszy ze wszystkich wolvarów!$B$BAle nie dlatego ja z tobą teraz gadać. Złe trolle przyjść i wykopać Wściekłe Pazury z nory. Wściekłe Pazury, co nie uciec, trzymane w niewoli w wiosce. Ty iść do Nory Wściekłych Pazurów, na południowy wschód, i uwolnić pojmane Wściekłe Pazury. Zabijać troll dla otwieracz zamków. Może zabić dużo troll dla dużo otwieracz zamków.', 'Wódz Wściekły Pazur w Wyłomie Światłości w Zul\'Draku chce, żebyś $guwolnił:uwolniła; 8 pojmanych Wściekłych Pazurów za pomocą „otwieraczy zamków” Drakuru, które noszą przy sobie różne trolle Drakuru.', '', 'Wróć do wodza Wściekłego Pazura w Wyłomie Światłości w Zul\'Draku.', 'Uwolnione pojmane Wściekłe Pazury', '', '', '', 0),
(12883, 'koKR', 'Rozkazy od Drakuru', 'Sługi, słuchać wezwania swego pana! Król Lisz dać Drakuru pełną władzę nad armiami Plagi w Zul\'Draku. Mamy rozkaz zabić wszystko.$B$BWSZYSTKO MUSI ZGINĄĆ!$B$BPrzerabiamy wszystkie trupy na Martwych Polach i wysyłamy je ekipie księcia Navariusa w Zeramas do uplagowienia! Nic się nie zmarnuje, póki Drakuru pilnuje!$B$BWkrótce będziemy pić krew proroków, by stać się silniejsi niż kiedykolwiek! Zul\'Drak i Gundrak padną przed Plagą!', 'Zanieś rozkazy od Drakuru lordowi krzyżowcowi Lantindze w Wyłomie Światłości w Zul\'Draku.', '', 'Wróć do lorda krzyżowca Lantingi w Wyłomie Światłości w Zul\'Draku.', '', '', '', '', 0),
(12884, 'koKR', 'Hebanowa Strażnica', 'Na zachód stąd, za zrujnowanymi drogami i budowlami, leży obozowisko rycerzy śmierci – Hebanowa Strażnica.$B$B<Lord krzyżowiec Lantinga zwija rozkazy Drakuru.>$B$BWeź te rozkazy i dostarcz je Stefanowi Vadu. To rycerz śmierci, który dowodzi w Hebanowej Strażnicy. Przekaż mu, że Krucjata Argentu zajmie się księciem Navariusem. Oni będą musieli poradzić sobie z Drakuru.$B$BUważaj na siebie, $N. Na drodze do Hebanowej Strażnicy roi się od Plagi.', 'Dostarcz rozkazy od Drakuru Stefanowi Vadu w Hebanowej Strażnicy w Zul\'Draku.', '', 'Zgłoś się do Stefana Vadu w Hebanowej Strażnicy w Zul\'Draku.', '', '', '', '', 0),
(12894, 'koKR', 'Wysunięty Obóz Krzyżowców', 'Krzyżowiec Dargath, krzyżowiec MacKellar, inżynier Reed i bliźniacy, Gerk i Burr, zostali kilka dni temu wysłani na Martwe Pola, by utworzyć tam front. Według mojej ostatniej wymiany wiadomości z nimi udało im się rozbić obóz na skraju Martwych Pól, na północny zachód stąd.$B$BW świetle tych nowych informacji o Drakuru i księciu Navariusie uważam, że rozsądnie byłoby czym prędzej wysłać kogoś do Wysuniętego Obozu Krzyżowców.$B$BSpakuj swoje rzeczy, $N. Musisz natychmiast wyruszać!', 'Odszukaj krzyżowca MacKellara w Wysuniętym Obozie Krzyżowców w Zul\'Draku.', '', '', '', '', '', '', 0),
(12901, 'koKR', 'Coś z niczego', 'Książę Navarius musi zostać powstrzymany. Nie możemy pozwolić, by Plaga dalej używała tego terenu jako fabryki zombie. Jeśli uda nam się uruchomić czołg, może będziemy mieli jakąś szansę. Teraz potrzebuję części zamiennych.$B$BNa północny zachód stąd leży miejsce zwane Kresem Thryma. Armie Plagi używają go jako swego rodzaju bazy. Po całej bazie rozrzucone są szczątki z ich przybycia. Kawałki złomu Plagi zaśmiecają całą okolicę. Przynieś mi to żelastwo, a spróbuję zrobić z niego użytek.', 'Inżynier Reed w Wysuniętym Obozie Krzyżowców w Zul\'Draku poprosił cię o zdobycie 10 kawałków złomu Plagi.', '', 'Wróć do inżyniera Reeda w Wysuniętym Obozie Krzyżowców w Zul\'Draku.', '', '', '', '', 0),
(12902, 'koKR', 'W poszukiwaniu odpowiedzi', 'Te biedne stworzenia to jedyni ocaleni.$B$BWedług ich wodza trolle Drakkarów i wolvary Wściekłych Pazurów są sojusznikami od tysięcy lat. Żyją tu obok trolli od pokoleń, zupełnie nieświadomi zmieniającego się wokół nich świata. Dla Wściekłych Pazurów troll to troll, więc atak trolli na ich norę całkowicie ich zaskoczył.$B$BPotrzebujemy odpowiedzi, $N. Przeszukaj ich wioskę – na południowy wschód stąd – w poszukiwaniu wskazówek, kto lub co stoi za tymi atakami.', 'Przeszukaj Norę Wściekłych Pazurów w poszukiwaniu wskazówki, kto lub co rozpoczęło ataki na wolvary Wściekłych Pazurów.', '', '', '', '', '', '', 0),
(12903, 'koKR', 'Od tego są przyjaciele...', 'Zaatakował nas książę Navarius z co najmniej tuzinem sług Plagi. Kazałem Dargathowi i bliźniakom zostać w czołgu, ale nie chcieli słuchać. Dargath spojrzał mi w oczy i powiedział: „Jeśli ktoś nie wyjdzie z tego czołgu, pozabijają nas wszystkich”. Potem kazał Reedowi zgasić silnik i ruszył do szarży. Najbardziej bohaterska rzecz, jaką w życiu widziałem.$B$BSłyszałem, jak książę wykrzykuje rozkazy do potworów. Brzmiało to tak, jakby zabierał ich do Kresu Thryma, na północny zachód stąd. Musimy ocalić naszych przyjaciół. Pójdziesz ich poszukać?', 'Krzyżowiec MacKellar w Wysuniętym Obozie Krzyżowców poprosił cię o odnalezienie krzyżowca Dargatha, Gerka i Burra.', '', 'Wróć do krzyżowca MacKellara w Wysuniętym Obozie Krzyżowców w Zul\'Draku.', 'Odnaleziony krzyżowiec Dargath', 'Odnaleziony Gerk', 'Odnaleziony Burr', '', 0),
(12904, 'koKR', 'Światłość nie da mi pomsty', 'Oni... Oni zabili mojego brata.$B$B<Gerk powstrzymuje łzy.>$B$BZarżnęli go jak jakieś zwierzę. Teraz leży na jednym z ich stołów po drugiej stronie obozu, gotowy na ich makabryczne eksperymenty. Dargath też nie żyje. Paladyn bohatersko stawił opór przy ruinach na północnym wschodzie, ale przywódca wargulów, Algar, był za silny.$B$BZostałem tylko ja, a wkrótce i ja umrę. Ja... ja się przemieniam.$B$BJeśli Światłość nie da mi pomsty, może ty mi ją dasz, $N. Zabij ich wszystkich.', 'Gerk przy Kresie Thryma w Zul\'Draku chce, żebyś $gzabił:zabiła; 15 wargulów.$B', '', 'Wróć do Gerka przy Kresie Thryma w Zul\'Draku.', 'Zabici wargule', '', '', '', 0),
(12912, 'koKR', 'Nadciąga wielka burza', 'Nie jesteś jak inni, mała istoto. Nie cuchniesz pradawną śmiercią. Może można ci zaufać.$B$BJestem Gymer, król burzowych olbrzymów. Zwabił mnie tu mój brat Thiassi, teraz nieumarły sługa Króla Lisza. Gdy zrozumiałem, że jego wołanie o pomoc było pułapką, było już za późno. Jestem teraz więźniem Plagi i obawiam się, że wkrótce spotka mnie ten sam los co wiele innych burzowych olbrzymów.$B$BZnajdź sposób, by uwolnić mnie z tej klatki, a pomogę ci, jak tylko zdołam.', 'Gymer, król burzowych olbrzymów, poprosił cię o znalezienie sposobu na uwolnienie go z klatki. Porozmawiaj z inżynierem Reedem w Wysuniętym Obozie Krzyżowców.', '', '', '', '', '', '', 0),
(12914, 'koKR', 'Ocalenie Gymera', 'Mówisz więc, że zamknęli go w klatce wysokiej na sto stóp, tak?$B$BJeśli moje obliczenia są poprawne, powinniśmy zdołać przynajmniej osłabić zawiasy klatki na tyle, by olbrzym mógł się wyrwać.$B$BŻeby to się udało, będę potrzebował plastyfikatorów i stabilizatorów.$B$BJako plastyfikator świetnie nada się esencja banshee. Zdobędziesz ją od banshee na Martwych Polach, na północny wschód od nas. Stabilizator znajdziesz przy furiatach ziemi na południowym zachodzie, niedaleko Hebanowej Strażnicy.$B$BRuszaj się!', 'Inżynier Reed w Wysuniętym Obozie Krzyżowców w Zul\'Draku chce, żebyś $gprzyniósł:przyniosła; mu 6 esencji banshee i 6 porcji ziemi okrzemkowej.', '', 'Wróć do inżyniera Reeda w Wysuniętym Obozie Krzyżowców w Zul\'Draku.', '', '', '', '', 0),
(12916, 'koKR', 'Nasza jedyna nadzieja', 'To, co ci zaraz dam, nazywa się seaforium. To wysoce niestabilny materiał wybuchowy o dość wyjątkowych właściwościach. Dzięki swojej plastyczności wypełnisz nim zawiasy i szczeliny klatki, by wybuch był jak najsilniejszy.$B$BWróć do swojego przyjaciela i użyj olbrzymiego ładunku z seaforium, by go uwolnić.$B$BMiejmy nadzieję, że dotrzyma umowy. To nasza jedyna nadzieja.', 'Porozmawiaj z Gymerem przy Kresie Thryma w Zul\'Draku, gdy już użyjesz olbrzymiego ładunku z seaforium, by otworzyć zagrodę Plagi, w której jest więziony.', '', 'Wróć do Gymera przy Kresie Thryma w Zul\'Draku.', 'Wysadzona zagroda Plagi', '', '', '', 0),
(12932, 'koKR', 'Amfiteatr Męczarni: Yggdras!', 'Powiem ci jedno: to miejsce to nie to samo co rozległe równiny Nagrandu. Te trolle są brudniejsze od ogrów, ale co tam, idę tam, gdzie jest złoto! Witaj więc w Zul\'Draku, $gkolego:koleżanko;.$B$BJesteś w tym interesie $gnowy:nowa;, więc wyjaśnię ci, jak to działa. Ja organizuję walki, a ten zadziorny troll obok mnie to Wodin, mój ochroniarz. Ty jesteś rozrywką. Kiedy zechcesz walczyć, daj mi znać, a ja ustawię pojedynek.$B$BJeśli jesteś $ggotów:gotowa; i masz ze sobą grupę przyjaciół, możemy zaczynać! Co ty na to?$B', 'Wejdź na arenę w Amfiteatrze Męczarni i pokonaj Yggdrasa! Wróć do Wodina Trollowego Sługi po nagrodę.', 'Yggdras pokonany', 'Wróć do Wodina Trollowego Sługi w Amfiteatrze Męczarni w Zul\'Draku.', '', '', '', '', 0),
(12933, 'koKR', 'Amfiteatr Męczarni: magnataur!', 'Następny pojedynek to prawdziwa perełka, $gkolego:koleżanko;! Podobno jakiś magnataur ze Smoczych Pustkowi chce uszczknąć coś dla siebie. $GWalczyłeś:Walczyłaś; już kiedyś z czymś takim? Mogę ci tylko powiedzieć: celuj wysoko!$B$BZaczniemy zabawę, jak tylko dasz znać.', 'Wejdź na arenę w Amfiteatrze Męczarni i pokonaj Smrodobrodego! Wróć do Wodina Trollowego Sługi po nagrodę.', 'Smrodobrody pokonany', 'Wróć do Wodina Trollowego Sługi w Amfiteatrze Męczarni w Zul\'Draku.', '', '', '', '', 0),
(12934, 'koKR', 'Amfiteatr Męczarni: z zaświatów!', 'Nie będę cię okłamywał, $gkolego:koleżanko;. Tym razem przeciwnik może cię przerastać. Następny to istota z planów żywiołów! Nawet ja nie wiem, co pojawi się na arenie!$B$BJeśli uważasz, że dasz radę, wchodź tam i daj im popalić!', 'Wejdź na arenę w Amfiteatrze Męczarni i pokonaj jednego z władców żywiołów! Wróć do Wodina Trollowego Sługi po nagrodę.', 'Władca żywiołów pokonany', 'Wróć do Wodina Trollowego Sługi w Amfiteatrze Męczarni w Zul\'Draku.', '', '', '', '', 0),
(12935, 'koKR', 'Amfiteatr Męczarni: Kiełzarmagedon!', 'Ten następny walczy, jakby wyszedł z bardzo mrocznego miejsca, $gmały:mała;. Z takiego mroku, jaki bierze się tylko stąd, że ktoś był już po drugiej stronie. Jest głodny i zrobi wszystko, żeby wygrać. Uważaj na siebie! Słyszałem, że dla rozgrzewki mocuje się z yeti!$B$BZaczniemy, kiedy będziesz $ggotów:gotowa;.', 'Wejdź na arenę w Amfiteatrze Męczarni i pokonaj Orinoko Łamikła! Wróć do Wodina Trollowego Sługi po nagrodę.', 'Orinoko Łamikieł pokonany', 'Wróć do Wodina Trollowego Sługi w Amfiteatrze Męczarni w Zul\'Draku.', '', '', '', '', 0),
(12936, 'koKR', 'Amfiteatr Męczarni: Korrak Krwawy Szaleniec!', 'Nie uwierzysz, $gkolego:koleżanko;. Twoja następna walka to starcie z Korrakiem Krwawym Szaleńcem! Wygląda na to, że trolle Drakkarów pokazują, kto tu rządzi! I powiem ci coś: on popijał soczek z bogów zwierząt. Jest w pełni gotów wbić cię w ziemię.$B$BJesteś $ggotów:gotowa;?', 'Wejdź na arenę w Amfiteatrze Męczarni i pokonaj Korraka Krwawego Szaleńca! Wróć do Wodina Trollowego Sługi po nagrodę.', 'Korrak Krwawy Szaleniec pokonany', 'Wróć do Wodina Trollowego Sługi w Amfiteatrze Męczarni w Zul\'Draku.', '', '', '', '', 0),
(12948, 'koKR', 'Czempion Męki', 'To już koniec, $gprzyjacielu:przyjaciółko;! Twój ostatni przeciwnik będzie twoim największym wyzwaniem. To wrykulski czempion ze stepów Lodowej Korony i jest żądny krwi! Pokonaj go, a zostaniesz $gukoronowany:ukoronowana; na $gczempiona:czempionkę; Amfiteatru Męczarni! Na tej walce $gobaj:oboje; się wzbogacimy!$B$BDaj znać, kiedy będziesz $ggotów:gotowa;, i zaczynamy.', 'Wejdź na arenę w Amfiteatrze Męczarni i pokonaj Vladofa Rzeźnika! Wróć do Wodina Trollowego Sługi po nagrodę.', 'Vladof Rzeźnik pokonany', 'Wróć do Wodina Trollowego Sługi w Amfiteatrze Męczarni w Zul\'Draku.', '', '', '', '', 0),
(12954, 'koKR', 'Amfiteatr Męczarni: Yggdras!', 'Już się zastanawiałem, kiedy się zjawisz, $N! $GByły czempion:Była czempionka; Kręgu Krwi przyciągnie tu tłumy! Będziemy bogaci, $gkolego:koleżanko;! BOGACI!$B$BW każdym razie ta nora to Zul\'Drak. Wszystkie lodowe trolle chyba traktują ją jak wychodek. Nie wiem, jak dla mnie całe to miejsce ma nie po kolei w głowie! Ale kogo to obchodzi, nie? Jesteśmy tu, żeby zarobić trochę złota!$B$BZnasz zasady, $N. Kiedy będziesz $ggotów:gotowa;, daj znać, a rozkręcimy to przedstawienie!$B', 'Wejdź na arenę w Amfiteatrze Męczarni i pokonaj Yggdrasa! Wróć do Wodina Trollowego Sługi po nagrodę.', 'Yggdras pokonany', 'Wróć do Wodina Trollowego Sługi w Amfiteatrze Męczarni w Zul\'Draku.', '', '', '', '', 0),
(12974, 'koKR', 'Wezwanie czempiona!', 'Pff, to, co się tu dzieje, to żadna walka. Paru gości tańczy wokół flagi.$B$BSzukasz prawdziwych emocji, $gkolego:koleżanko;? Bo jeśli tak, to mam najgorętszy bilet w mieście.$B$B$GSłyszałeś:Słyszałaś; kiedyś o Gurgthocku i Wodinie? Goblinie i trollu, którzy prowadzili Krąg Krwi w Rubieży? No więc są teraz w Północnej Grani i otworzyli zupełnie nowy klub walk w Zul\'Draku. Jeśli cię to interesuje, jedź do Zul\'Draku, na wschód od Lasu Kryształowej Pieśni. Są na wielkiej arenie pośrodku. Powiedz im, że przysłał cię Śliski!', 'Odszukaj Gurgthocka w Amfiteatrze Męczarni w Zul\'Draku.', '', '', '', '', '', '', 0),
(13027, 'koKR', 'Nestor Tauros', '', '', '', '', '', '', '', '', 0),
(13096, 'koKR', 'Gal\'darah musi zapłacić', '$GWidziałeś:Widziałaś; to, mon?$b$bTo musiała być najgorsza rzecz, jaką kiedykolwiek widziałem. Wielki Akali – zabity na moich oczach. Straszne...$b$bZłożyłem przysięgę, że nie będę się w nic tutaj mieszał. Moja robota to tylko patrzeć. Ale tak być nie może! Gal\'darah musi zapłacić!$b$bIdź do Gundraku i go odszukaj. Wróć do mnie, jak śmierć Akaliego zostanie pomszczona, mon.', 'Tol\'mar w Dubra\'Jin chce, żebyś $gzabił:zabiła; Gal\'daraha w Gundraku.', '', 'Wróć do Tol\'mara w Dubra\'Jin w Zul\'Draku.', 'Gal\'darah zabity', '', '', '', 0),
(13098, 'koKR', 'Dla potomnych', 'Gundrak jest zgubiony, mon.$b$bHistoria powtarza się na naszych oczach. Kiedy trolle zwracają się przeciw własnym bogom, koniec jest pewny. To tylko kwestia czasu.$b$bMoże jak dokładnie spiszemy te wydarzenia, uchronimy przyszłe pokolenia przed pójściem tą samą drogą.$b$bJeśli starczy ci odwagi, wejdź do Gundraku i szukaj śladów tego, co doprowadziło Imperium Drakkarów do takiego końca.', 'Kronikarka Bah\'Kini w Dubra\'Jin chce, żebyś $gwszedł:weszła; do Gundraku i $gzebrał:zebrała; 6 tablic z historią Drakkarów.', '', 'Wróć do kronikarki Bah\'Kini w Dubra\'Jin w Zul\'Draku.', '', '', '', '', 0),
(13099, 'koKR', 'Tylko sprawdzam', 'Z Gundraku dochodzą przerażające odgłosy. Ostatnio są coraz głośniejsze i coraz częstsze.$b$bMoja długoletnia uczennica spisuje obecnie wydarzenia ze swojego posterunku tuż na zachód od Gundraku. Może $gznalazłbyś:znalazłabyś; czas, żeby do niej zajrzeć w moim imieniu?', 'To\'kini chce, żebyś $gporozmawiał:porozmawiała; z Bah\'Kini w Dubra\'Jin.', '', '', '', '', '', '', 0),
(13549, 'koKR', 'Ogony w górę', 'Oprócz artefaktów Drakkarów chciałbym zabrać do Zandalaru trochę zwierząt z Zul\'Draku. Mam samców mroźnych lampartów i lodowołapych niedźwiedzi, ale potrzebuję samic!$B$BSzkoda, że mój traper zginął w wielce niefortunnym wypadku. Może $gzechciałbyś:zechciałabyś; go zastąpić?$B$BUśpij lamparty i niedźwiedzie tą dmuchawką, potem podnieś im ogony i, jeśli łaska, wróć z kilkoma samicami. Znajdziesz je w pobliżu Ołtarzy Rhunoka, Quetz\'lun i Har\'koi.', 'Kronikarz To\'kini w Zim\'Torga chce, żebyś $gużył:użyła; dmuchawki To\'kiniego na mroźnych lampartach i lodowołapych niedźwiedziach. Wróć do niego z 3 samicami każdego gatunku.', '', 'Wróć do kronikarza To\'kiniego w Zim\'Torga w Zul\'Draku.', 'Zdobyte samice mroźnego lamparta', 'Zdobyte samice lodowołapego niedźwiedzia', '', '', 0),
(13556, 'koKR', 'Jaja dla Dubra\'Jin', 'Jak leci, mon? Myślisz, że mi pomożesz? Bah\'Kini trza dużo jaj raptorów, żeby złożyć je w ofierze Dubra\'Jin.$B$BJak myślisz, czemu Drakkarowie jeszcze nas nie zalali? Bo Dubra\'Jin nam pomaga!$B$BTrza, żebyś $gzebrał:zebrała; jaja raptorów spod drzew tu, przed Gundrakiem. Czasem raptory noszą je przy sobie, żeby je grzać.', 'Ha\'wana w Dubra\'Jin potrzebuje, żebyś $gzebrał:zebrała; 12 jaj raptorów z Gundraku.', '', 'Wróć do Ha\'wany w Dubra\'Jin w Zul\'Draku.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(12501, 'koKR', 'Cóż, $N, przynajmniej $gwróciłeś:wróciłaś; w jednym kawałku. To chyba już coś...', 0),
(12502, 'koKR', 'Dobra robota, $gprzyjacielu:przyjaciółko;.$B$BNiesamowite, co z polem bitwy potrafi zrobić odrobina własnych barw.$B$BTeraz udaj się do kapitana Ruperta. Stacjonuje przy murze, tuż na północny wschód stąd.', 0),
(12503, 'koKR', 'Bardzo doceniam twoją pomoc w tej sprawie. Gdyby nie twoje wysiłki, z trudem powstrzymywalibyśmy nieumarłych przed naszym progiem.', 0),
(12504, 'koKR', 'No dobra. Zbierzemy resztę i wracamy do Reduty.$B$BSzkoda, że musimy się tak szybko wynosić. Nie wygląda na to, żeby robota była tu skończona, a szczerze mówiąc, mam przeczucie, że ten prorok przed ołtarzem narobi nam sporo kłopotów!', 0),
(12505, 'koKR', '<Krasnoludzki sierżant nieufnie spogląda na rozkazy w twojej dłoni.>$B$BTo nowe rozkazy dla mnie, $gpanie:panienko;?', 0),
(12506, 'koKR', 'Martwy?$B$B<Wieść, którą przynosisz, wyraźnie odbiera rzucaczowi uroków ducha.>$B$BZabili Sseratusa i napili się do syta jego mojo – zwłaszcza prorok!$B$BMusimy znaleźć sposób, żeby z nim skończyć, zanim wypije go jeszcze więcej!', 0),
(12507, 'koKR', 'To mojo dzikich bogów, $N!$B$BNiedobrze!', 0),
(12508, 'koKR', 'Dzięki, $N. Nie chciałabym odejść, nie zrobiwszy tego, po co w ogóle tu przyszliśmy.', 0),
(12509, 'koKR', 'Dobra robota, $N. I w samą porę. Dostałem wiadomość, że lada chwila nastąpi kontratak.$B$BLepiej ruszaj w drogę. Następny posterunek jest na północnym wschodzie, niedaleko koloseum. Powinien tam na ciebie czekać kapitan Grondel.', 0),
(12510, 'koKR', 'Doskonale. Połączone z mojo, te płyny osłabią jego działanie, ale całkiem go nie zniwelują.$B$BTeraz jeszcze jedno.', 0),
(12512, 'koKR', '$GUratowałeś:Uratowałaś; wszystkich, tak? Znakomicie!$b$bMoże $gzastanowiłbyś:zastanowiłabyś; się nad pozostaniem tu na posterunku? Ktoś taki jak ty bardzo by się nam przydał...', 0),
(12514, 'koKR', '<Rzucacz uroków kiwa głową z aprobatą.>$B$BDaj mi te grzyby, a zmieszam je z mojo i płynami władców żywiołów.', 0),
(12516, 'koKR', 'Niesamowite! $GOcaliłeś:Ocaliłaś; swoich ludzi i resztę Północnej Grani przed jego szaleństwem.$B$BNiestety, ten obłęd szerzy się też na wyższych poziomach Zul\'Draku.', 0),
(12519, 'koKR', 'No proszę!$B$B$GOszczędziłeś:Oszczędziłaś; mi sporo roboty, $gchłopcze:dziewczyno;. Jestem wdzięczny. Na pewno wspomnę o tobie w raporcie.$B$BA teraz zmykaj. Finklestein pewnie czeka na ciebie kawałek na zachód stąd.', 0),
(12527, 'koKR', 'Och, wyśmienicie! Dziękuję. Kryształy wyglądają na nienaruszone!$B$BNie wątpię, że to Pestlepot namówił cię do odwalania za niego jego obowiązków. Niemniej bardzo doceniam twoją pomoc w tej sprawie!', 0),
(12541, 'koKR', 'Udało ci się!$B$BInformacje wydobyte z tego trolla bez wątpienia okażą się bardzo cenne. Na pewno wspomnę o twoich wysiłkach w raporcie dla dowódcy.$B$BDziękuję, $N.', 0),
(12552, 'koKR', 'To za mało!$B$B<Głos sierżanta się łamie, gdy opłakuje splugawienie swoich poległych towarzyszy.>$B$BMusimy zrobić więcej, by uczcić pamięć tych ludzi!', 0),
(12553, 'koKR', 'Nadadzą się!$B$BTeraz potrzebujemy trochę surowych części, żebym mogła złożyć dla ciebie urządzenie miotające.', 0),
(12554, 'koKR', 'Jesteś $gbohaterem:bohaterką; dnia, $N.$B$B<Księżycowy Odłamek odkopuje od siebie głowę.>$B$BZasługujesz na nasz najgłębszy szacunek i chyba na coś jeszcze.', 0),
(12555, 'koKR', 'Hurra! Jesteś $gnajlepszy:najlepsza;, $N!$B$BNa pewno nie marzyłam o tym, żeby mnie opryskano paskudztwem Plagi! Teraz tym głupim nerubianom będzie chyba trudno szerzyć swoje zło!$B$BMoże dam ci coś w podzięce za uratowanie mi skóry?', 0),
(12557, 'koKR', 'Tak, tak, to dobry początek.$B$BJeśli poproszę cię o pomoc przy prawdziwej recepturze, będziesz $gmusiał:musiała; odnajdywać składniki bez zwłoki.$B$BPamiętaj o tym, $N.$B$BŻegnaj.', 0),
(12562, 'koKR', 'Świetna robota, $gpanie:pani;!$B$BDopilnuję, żeby dowódca został poinformowany o wynikach twojej misji.', 0),
(12563, 'koKR', 'Cóż, $N, przynajmniej $gwróciłeś:wróciłaś; w jednym kawałku. To chyba już coś...', 0),
(12564, 'koKR', 'Piękne okazy, $N.$b$bW imieniu moich żołnierzy dziękuję ci za dzisiejszy trud.$b$bNastępnym przystankiem twojego patrolu będzie pewnie kapitan Rupert. Stacjonuje przy murze, tuż na wschód stąd.', 0),
(12565, 'koKR', '<Gdyby Zim\'Abwa mógł poruszyć twarzą, uśmiechnąłby się okrutnie.>', 0),
(12567, 'koKR', '<Wyczuwasz aprobatę Zim\'Abwy. Jakimś sposobem wiesz, że Zim\'Abwa chce więcej daniny!>', 0),
(12568, 'koKR', 'Dziękuję, $N.$B$BTo nie jest najchwalebniejsza robota na polu bitwy, ale ktoś musi ją wykonać. Odnotuję twoją służbę w raporcie.$B$BKapitan Grondel pewnie czeka na ciebie na północnym wschodzie, tuż przed amfiteatrem.', 0),
(12583, 'koKR', '<Specjalistka cofa się nieco na widok części.>$b$bFuj, ale obrzydlistwo!$b$bNo dobra, dobra, dawaj je, zobaczę, co da się zrobić. Chyba powinnam była kazać ci najpierw zanieść je kapłanowi do oczyszczenia.', 0),
(12584, 'koKR', 'Czy nie czujesz czystego zła, jakie od tego bije?$b$bMusimy połączyć wiedzę i magię, którymi dysponujemy, z mocą Świętej Światłości, by przebić zasłonę nieprawości spowijającą tę skażoną rudę. Musimy ustalić jej pochodzenie.$b$bSzybko, daj mi saronit!', 0),
(12585, 'koKR', 'Wielkie dzięki, $N. Naprawdę wielkie.$b$bKapitana Arnatha znajdziesz prosto na zachód stąd, tuż za wzniesieniem.', 0),
(12587, 'koKR', 'Cóż, $N, przynajmniej $gwróciłeś:wróciłaś; w jednym kawałku. To chyba już coś...', 0),
(12588, 'koKR', 'Dziękuję, że się tym dla mnie $gzająłeś:zajęłaś;, $N. Wspomnę o twojej służbie w raporcie.$b$bTeraz pewnie zechcesz odwiedzić kapitana Ruperta. Stacjonuje przy murze, prosto na wschód stąd.', 0),
(12591, 'koKR', 'Wcale jeszcze nie wyszliśmy na prostą, ale dzięki tobie wróg zwolnił.$b$bKapitan Grondel w Drak\'Agal pewnie będzie cię potrzebował.$b$bBywaj, $N.', 0),
(12594, 'koKR', 'Na pewno, $N?$b$bMam wrażenie, że jest ich tam teraz więcej niż wtedy, gdy $gzaczynałeś:zaczynałaś;!', 0),
(12596, 'koKR', 'Najwyższy czas, żebyś $gprzywlókł:przywlokła; tu z powrotem swoje truchło! Myślałem, że Plaga cię dopadła – nie żeby to była wielka strata...$b$bJeśli chcesz dalej służyć Krucjacie, lepiej się bardziej postaraj.$b$bZapamiętaj, $N! Za kolejne patrole nagroda będzie zależeć od tego, jak szybko się uwiniesz.$b$bOdmaszerować.', 0),
(12597, 'koKR', 'Piękne okazy, $N.$b$bW imieniu moich żołnierzy dziękuję ci za dzisiejszy trud.$b$bNastępnym przystankiem twojego patrolu będzie pewnie kapitan Rupert. Stacjonuje przy murze, tuż na wschód stąd.', 0),
(12598, 'koKR', 'Wcale jeszcze nie wyszliśmy na prostą, ale dzięki tobie wróg zwolnił.$b$bKapitan Grondel w Drak\'Agal pewnie będzie cię potrzebował.$b$bBywaj, $N.', 0),
(12599, 'koKR', 'Wielkie dzięki, $N. Naprawdę wielkie.$b$bStarego Finklesteina znajdziesz prosto na zachód stąd, tuż za wzniesieniem.', 0),
(12604, 'koKR', 'Patrol poszedł ci wyjątkowo sprawnie. Wygląda na to, że jednak możesz się nam przydać.$b$bJak obiecałem, oto mały dodatek za twój trud.$b$bTak trzymaj, $N.$b$bOdmaszerować.', 0),
(12606, 'koKR', 'Nerubianie zebrali krwawe żniwo, $N.$b$bMimo to jestem wdzięczny za twoje wysiłki.', 0),
(12609, 'koKR', 'Wyglądają na znakomite próbki, $N.$b$bDziękuję za pomoc.', 0),
(12610, 'koKR', 'Świetna robota, $N.$b$bDziękuję za pomoc.', 0),
(12615, 'koKR', '<Myśli Zim\'Torgi przenikają twoje. Bogini wyczuwa ofiary, które zamierzasz jej złożyć, i jest zadowolona.>$b$b<Daje ci do zrozumienia, że zostaniesz odpowiednio $gnagrodzony:nagrodzona;.>', 0),
(12618, 'koKR', '<Matka Dobrobytu obdarza cię promiennym spojrzeniem pełnym aprobaty.>', 0),
(12622, 'koKR', 'Łowca skalpów myśli, że ty to ktoś w jego guście!$b$bA co tu robią te batoniki? Co my z tym zrobić, mon?$b$bAhunae mówi, że możesz je sobie wziąć z powrotem!', 0),
(12623, 'koKR', 'Witaj, $N. Cieszę się, że Ubungo znalazł kogoś, komu może zaufać.$b$bWitaj w Zim\'Torga.', 0),
(12627, 'koKR', 'Tak, już czuję różnicę. Dziękuję.$b$bZobaczmy, czy uda się teraz nawiązać kontakt z bogami.', 0),
(12628, 'koKR', 'Słuchaj uważnie, maleństwo. Czas nagli.', 0),
(12629, 'koKR', '<Stefan przebiera w plugawych składnikach.>$b$bCóż, daleko temu do doskonałości, ale musi wystarczyć. A teraz przygotuj się, $N. Teraz zacznie się najlepsze...', 0),
(12630, 'koKR', 'Wiesz, strasznie przypominasz mi mojego Nassa.$b$bMoże to przez nos...', 0),
(12631, 'koKR', 'Istotnie, znam takie przedmioty.$b$b<Stefan patrzy ci w oczy.>$b$bWygląda na to, $N, że $gzostałeś:zostałaś;... $gwybrany:wybrana;.', 0),
(12632, 'koKR', 'Dziękuję, $N. Nigdy nie zapomnę, co dla mnie $gzrobiłeś:zrobiłaś;.', 0),
(12633, 'koKR', 'Istotnie, znam takie przedmioty.$b$b<Stefan patrzy ci w oczy.>$b$bWygląda na to, $N, że $gzostałeś:zostałaś;... $gwybrany:wybrana;.', 0),
(12635, 'koKR', 'Och, pierwszorzędne okazy!$b$bWidać tu odejście od pierwotnej symboliki. Doprawdy niezwykłe.$b$bJaka szkoda, że lodowe trolle tak uparcie dążą do własnej zagłady.$b$bCzy wiesz na przykład, że Drakkarowie zostali wygnani przez resztę trollowych narodów za swoją skrajną brutalność?$b$bNaprawdę! A jak myślisz, skąd trolle wzięły się w tak surowym klimacie?', 0),
(12637, 'koKR', 'Teraz już wiesz, jaki los miał cię spotkać.$b$bJak już mówiłem, to nie był przypadek. Stworzenie takiego przedmiotu jest bardzo pracochłonne, a potrzebnych zasobów nie marnowałoby się na przypadkowy cel.$b$bPrawda jest po prostu taka: Plaga cię poszukuje...', 0),
(12638, 'koKR', 'Teraz już wiesz, jaki los miał cię spotkać.$b$bJak już mówiłem, to nie był przypadek. Stworzenie takiego przedmiotu jest bardzo pracochłonne. Jakimś sposobem $gzwróciłeś:zwróciłaś; na siebie uwagę przywódców Plagi.$b$bPytanie nie brzmi: jak, dlaczego ani nawet kto... lecz co z tym zrobimy?', 0),
(12639, 'koKR', 'Dziękuję, $N. Te esencje powinny na długo zasilić moje zaklęcia.', 0),
(12640, 'koKR', 'Ahunae ma nadzieję, że Dagoda dostała wszystkich obrońców, co chciała. Jak szczeliny zamknięte, to raczej więcej nie dostanie.', 0),
(12642, 'koKR', 'Ledwo się trzymam. Musisz działać szybko, bo wszystko przepadnie.', 0),
(12643, 'koKR', '<Stefan przebiera w plugawych składnikach.>$b$bCóż, daleko temu do doskonałości, ale musi wystarczyć.$b$bA teraz przygotuj się, $N. Teraz zacznie się najlepsze...', 0),
(12646, 'koKR', 'Udało ci się.$b$bAle teraz musisz zrobić dla mnie jeszcze jedną rzecz.', 0),
(12647, 'koKR', '$GZrobiłeś:Zrobiłaś;, co trzeba było zrobić, i przy tym $goddałeś:oddałaś; mi cześć.$b$bZ głębi serca ci dziękuję, $N. Mam tylko nadzieję, że ty i Har\'koa zdołacie pomóc pozostałym.', 0),
(12648, 'koKR', 'No i jak? Podoba ci się życie w Pladze?$b$bUwierz mi, nie jest takie wspaniałe, jak mówią...', 0),
(12649, 'koKR', 'No i jak? Podoba ci się życie w Pladze?$b$bUwierz mi, nie jest takie wspaniałe, jak mówią...', 0),
(12650, 'koKR', 'Pokaż mi je.$b$b<Kronikarz bada artefakty, które $godzyskałeś:odzyskałaś;.>$b$bHm, powiedziałbym, że mamy szczęście, iż $guwolniłeś:uwolniłaś; je w samą porę, $N.$b$bJakie to ciekawe. Ten artefakt przedstawia wydarzenia Wielkiego Rozłamu. Był czas, gdy Północna Grań stanowiła najdalszą północną część Kalimdoru.$b$bAle po Rozłamie ląd się oderwał i z czasem stał się Północną Granią.$b$bDlatego właśnie Drakkarów spotykamy zarówno na południowych kontynentach, jak i tutaj.', 0),
(12652, 'koKR', 'Mniam, mniam!', 0),
(12653, 'koKR', '<Kocia bogini wyje z bólu.>$b$bMój duch krzyczy z żalu po stracie kolejnego przyjaciela. Ale nie lękaj się – on powróci, a jego duch będzie żył wiecznie.', 0),
(12655, 'koKR', '<Zim\'Rhuk przyjmuje do wiadomości ofiary, które zamierzasz przed nim złożyć, choć wie, że $gzabrałeś:zabrałaś; je ze zwłok innych.>$b$b<Jeśli mu je dasz, niechętnie zgodzi się udzielić ci swojego błogosławieństwa.>', 0),
(12656, 'koKR', '<Zim\'Rhuk wtłacza ci do umysłu obraz jednego ze swoich strażników, który rozgniata cię stopą. Może warto udobruchać Zim\'Rhuka kolejnymi ofiarami.>', 0),
(12659, 'koKR', 'Ha, Ahunae myśli, że to bardzo śmieszne.$b$b$N to ktoś w moim guście!$b$bMasz jeszcze mój nóż?', 0),
(12661, 'koKR', 'No, no... Muszę przyznać, że jestem mocno zaskoczony, że cię widzę, $N.$b$bPowiedz mi, czego się $gdowiedziałeś:dowiedziałaś;.', 0),
(12662, 'koKR', 'Udało ci się!$b$b<Dagoda całuje cię mocno w policzek.>$b$bNie masz pojęcia, jaka to dla mnie ulga! Obrona przed trollami ze wszystkich stron naprawdę nas wyczerpuje. Nie wspominając o jego bezustannych wrzaskach.$b$bProszę, $N, wybierz, co zechcesz, z tego, co mamy do zaoferowania.', 0),
(12663, 'koKR', 'No, to teraz widzisz, z czym się mierzymy, mon.$b$bZejdź na dół, poświęć trochę czasu, żeby poznać teren, przygotuj jakąś strategię.$b$bNiedługo będę miał dla ciebie zadania.', 0),
(12664, 'koKR', 'No, to teraz widzisz, z czym się mierzymy, mon.$b$bChcę, żebyś $gzszedł:zeszła; na dół, $gpoznał:poznała; teren, $gpobratał:pobratała; się ze swoimi braćmi. Przygotuj się...$b$bNiedługo będzie dla ciebie dużo roboty. Nie waż się mnie zawieść!', 0),
(12665, 'koKR', 'Dziękuję, że bezpiecznie $gsprowadziłeś:sprowadziłaś; moje kocię z powrotem.$b$bW głębi duszy to wiedziałam. Chciałam temu zaprzeczyć, ale twoje oczy odsłoniły prawdę.$b$bMimo to wyczuwam coś jeszcze. Nie wszystko jest takie, jak się wydaje.', 0),
(12666, 'koKR', '<Bogini lampartów patrzy ze smutkiem na zbiór świętych symboli, który przed nią $gpołożyłeś:położyłaś;.>$b$bKiedyś coś znaczyły. Zobaczmy, czy uda się zrobić z nich lepszy użytek.', 0),
(12667, 'koKR', 'Nędzny robaku. Powiedz mi, czemu nie miałabym cię unicestwić tam, gdzie stoisz?', 0),
(12668, 'koKR', 'Wyśmienicie. Może jednak się na coś przydasz.', 0),
(12669, 'koKR', 'Dobra robota, $N!$b$bRozcieńczenie zawartości tych kotłów nie tylko ocali życie wielu istot, ale też spowolni rozrost Plagi w tym regionie.$b$bA teraz chodź, opowiedz mi, czego się $gdowiedziałeś:dowiedziałaś; o strategii Drakuru w Zul\'Draku.', 0),
(12672, 'koKR', 'Wystarczą. Pewnie nawet nie będą mi potrzebne.$b$bAle zabawnie było patrzeć, jak biegasz na moje rozkazy.', 0),
(12673, 'koKR', 'Kryształy piętrzą się jak nigdy dotąd!$b$bTak trzymaj, $N. Niedługo mam dla ciebie więcej zadań.', 0),
(12674, 'koKR', '<Straszliwy duch przed tobą wybucha mrożącym krew w żyłach rechotem.>$b$bSami się o to prosili. A ja będę im to dawać znowu i znowu, i znowu...', 0),
(12675, 'koKR', 'Cząstkę mojego ducha?$b$b<Bogini śnieżnych lampartów zastanawia się przez chwilę.>$b$bTo dość kosztowny dar, zważywszy, że chodzi o zemstę, a ja już jestem mocno osłabiona przez moich poskramiaczy.$b$bMimo to może znam pewien sposób.', 0),
(12676, 'koKR', 'Doskonale!$b$bTwoja praca pod przykrywką naprawdę się opłaciła, $N.$b$bA teraz przyjrzyjmy się temu berłu...', 0),
(12677, 'koKR', 'Fascynujące!$b$bNatychmiast zbadamy właściwości tych kryształów.$b$bA teraz powiedz mi, $N, co nowego u tego całego Drakuru?', 0),
(12684, 'koKR', 'Dobrze. Zobaczmy, czy to zadziała...', 0),
(12685, 'koKR', '<Znachor kręci głową z niedowierzaniem.>$b$bWygląda na to, że ledwo $guszedłeś:uszłaś; z życiem z zaświatów Quetz\'lun.$b$bCieszę się, że to ty tam jesteś. Nie wiem, czy ja miałbym odwagę stawić czoła takiej sytuacji!', 0),
(12686, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. Uczysz się szybciej, niż się spodziewałem.$b$bIdź teraz, odpocznij trochę. Niedługo dam ci jeszcze większą próbę!', 0),
(12690, 'koKR', 'Udało się, mon!$b$bMam wszystkich wodzów w klatkach, a ty $gpoprowadziłeś:poprowadziłaś; moje plugastwa do zwycięstwa nad ich armiami.$b$bCzas świętować, mon!', 0),
(12707, 'koKR', 'Punkt dla ofiar, mon!', 0),
(12708, 'koKR', 'To powinno sprawić, że zastanowią się dwa razy, zanim zrobią ich więcej. Drżę na myśl o walce z całą armią tych stworów.$b$b<Poskramiaczka żywiołów przez chwilę się zamyśla.>$b$bChociaż to byłoby pewnie jak walka z niekończącymi się falami Plagi.', 0),
(12709, 'koKR', 'Tylko spójrz na to wszystko!$b$bZobacz, $N. Ten przedmiot, który $godzyskałeś:odzyskałaś;, dobitnie pokazuje, że Drakkarowie dostrzegli osłabienie ziemi spowodowane obecnością Plagi.$b$bWódz wojenny poczuł, że musi wykorzystać tę okazję. Nakłonił proroków do zabicia swoich bogów, by zapanować nad ich mocą i odeprzeć siły Króla Lisza.$b$bTak czy inaczej, byli zgubieni. Mimowolnie sami stali się narzędziem własnej zagłady!', 0),
(12710, 'koKR', 'No, to już wiesz, mon.$b$bTworzymy najlepszą armię Plagi, żeby służyła Królowi Liszowi. On będzie bardzo zadowolony!$b$bZatrzymaj berło, $N. Będzie ci potrzebne, żeby dowodzić moją armią w bitwie...$b$bJuż niedługo!', 0),
(12712, 'koKR', 'Może lepiej by było, gdybym nie prosiła cię o przyniesienie go tutaj, tylko od razu wysłała cię do Gundraku.$b$bSądzę jednak, że najpierw $gpowinieneś:powinnaś; wysłuchać, co jeszcze mam do powiedzenia.', 0),
(12713, 'koKR', 'A więc stało się.$b$bWciąż mamy wiele do zrobienia, ale dzięki twoim wysiłkom nasza praca tutaj będzie znacznie łatwiejsza.$b$bPrzyjmij to w dowód naszej wdzięczności.', 0),
(12721, 'koKR', 'Nie!$b$bKolejny bóg zniszczony, jego moc skradziona. A teraz prorok Akaliego zagroził nam bezpośrednio.$b$bGdy przyjdzie, przyjdzie po Har\'koę. Nie możemy pozwolić, by odebrał i jej moc.$b$bMusimy jeszcze raz poradzić się bogów, $N. Oni powiedzą nam, co trzeba zrobić.', 0),
(12729, 'koKR', 'Twoja odwaga zdaje się nie mieć granic, $N.$B$BPodaj mi serce i esencję, a zrobię z nich coś, co zmusi proroka, by stanął przed tobą.', 0),
(12730, 'koKR', 'Udało ci się! $N, jesteś $gczempionem:czempionką; Zul\'Draku!$B$BNigdy nie zdołamy spłacić długu, jaki u ciebie zaciągnęliśmy, ale Zandalarowie powierzyli mi kilka przedmiotów, które ich zdaniem mogą cię zainteresować.$B$BProszę, przyjmij coś w dowód naszej wdzięczności, ale pospiesz się. Wyczuwam kolejną pilną sprawę!', 0),
(12740, 'koKR', '$gDobry z ciebie człowiek:Dobra z ciebie kobieta;, $N. Mamy szczęście, że akurat tędy $gprzechodziłeś:przechodziłaś;.$B$BZostań tu na jakiś czas. Na pewno znajdzie się wiele zajęć dla kogoś tak zdolnego jak ty.', 0),
(12792, 'koKR', 'Mój raport musiał dotrzeć do Kunza.$b$bDobrze wiedzieć, że nic mu nie jest.', 0),
(12795, 'koKR', 'Tak się składa, że możesz nam w czymś pomóc, $N.', 0),
(12799, 'koKR', 'Dziękuję, $N.$b$bTo zaoszczędzi moim ludziom sporo cennego czasu.', 0),
(12857, 'koKR', '<Wódz Wściekły Pazur płacze.>$B$BMieć Wściekłogrzywego od szczenięcia. Smutny dzień dla Wściekłego Pazura. Najpierw troll atakować Wściekłe Pazury, potem troll robić Wściekłogrzywego złym. Wściekły Pazur nigdy więcej nie handlować z troll!', 0),
(12859, 'koKR', 'Dziwne, bo wiem, że ty gasić ogień, a ogień dalej się palić. Może to coś nie takie dobre, co? Ale Moky i tak ci zapłacić za to, co zrobić! Oby troll też się spalić!', 0),
(12861, 'koKR', 'Wściekły Pazur dziękować, $N. Choć Nora Wściekłych Pazurów pewnie stracona na zawsze i przyjaźń trolli z Wściekłymi Pazurami też stracona na zawsze... i jak teraz o tym myśleć, Wściekłogrzywy też stracony na zawsze. I szwagier. On przepaść. Hrm, widzieć może żona wodza? Ja myśleć, ona też przepaść.$B$BMoże ty już iść. Wódz trochę przygnębiony.', 0),
(12883, 'koKR', 'Jeśli to ten sam Drakuru co w Twierdzy Drak\'Tharon, będziemy potrzebowali... pomocy z zewnątrz.$B$BW pobliżu stacjonują rycerze śmierci z Acherusu, bez wątpienia idący tym samym szlakiem zniszczeń Plagi, który przywiódł tu Krucjatę Argentu. Połowa naszej armii jest uwiązana w Reducie Argentu, walcząc z oszalałymi trollami Drakkarów, więc będziemy musieli połączyć siły z Rycerzami Hebanowego Miecza.$B$B<Lantinga mruczy coś pod nosem.>$B$BMiałem nadzieję, że po Kaplicy Świetlistej Nadziei już nigdy nie będę musiał oglądać tych łotrów...', 0),
(12884, 'koKR', '<Stefan czyta wiadomość, po czym zgniata ją i wrzuca do ognia.>$B$BStare wieści. Krucjata Argentu – po raz kolejny – spóźnia się na przyjęcie. Tropimy Drakuru od Wzgórz Grizli. Jest przeznaczony do likwidacji.\n', 0),
(12894, 'koKR', 'Wszystko było w porządku, dopóki nie zaatakowała Plaga. Porwali Dargatha, Gerka i Burra, a do tego zniszczyli nasz pojazd. Zgadnij, kto prowadził ten atak?$B$B<MacKellar kiwa głową.>$B$BNavarius...$B$BWygląda na to, że cała ta okolica to jakaś fabryka Plagi. Jesteśmy w samym środku przeklętego nieumarłego pola minowego!', 0),
(12901, 'koKR', 'Co to za graty! Ach, do licha! To bezużyteczne. Metal Plagi się nie nada. Co my teraz zrobimy?', 0),
(12902, 'koKR', 'Nad dziwnym ołtarzem unosi się w powietrzu zwój. To musi być to, czego szuka lord krzyżowiec Lantinga!', 0),
(12903, 'koKR', 'Tych troje złożyło wielką ofiarę i szybko o niej nie zapomnimy. Ich śmierć nie pójdzie na marne. Zwyciężymy!', 0),
(12904, 'koKR', '<Gerk umiera.>$B$BM... Mówią, że te wargule to... ci, których Król Lisz uznał za niegodnych. Czy... czy ty to sobie wy... wyobrażasz? Po... pomyśl, jak potężni muszą być... ci... godni...$B$BPomodlę się za ciebie na tamtym świecie, $gbohaterze:bohaterko;... Obyś nigdy nie $gmusiał:musiała; stawić im czoła w wielkiej liczbie.', 0),
(12912, 'koKR', 'B... Burzowy olbrzym? Nie wiem, co o tym myśleć, $N. Brzmi ryzykownie. Z drugiej strony chyba nie mamy zbyt wielu innych możliwości.$B$BJeśli to zrobię, musisz mi obiecać, że twój przyjaciel olbrzym pomoże nam rozprawić się z Navariusem i jego kompanami.', 0),
(12914, 'koKR', 'Na szczęście nie brakowało nam materiałów wybuchowych. Złożenie olbrzymiego ładunku z seaforium z materiałów, które $gprzyniosłeś:przyniosłaś;, nie powinno sprawić problemu.', 0),
(12916, 'koKR', 'WOLNOŚĆ!$b$bNie lękaj się, mała istoto. Gymer to honorowy olbrzym. Tak jak ty i twój lud, ja również pragnę ujrzeć Plagę przepędzoną z tej ziemi, a Króla Lisza zniszczonego. Pomogę ci, jak obiecałem, najlepiej jak potrafię.', 0),
(12919, 'koKR', 'Niewiarygodne! To będzie opowieść na wieki, $N! $gJeden śmiałek jechał:Jedna śmiałczyni jechała; na głowie króla burzowych olbrzymów i $gzdziesiątkował:zdziesiątkowała; całą armię Plagi!$b$bA ja byłem przy tym i wszystko widziałem...', 0),
(12932, 'koKR', 'Nieźle, $gkolego:koleżanko;. Możesz tu zarobić trochę złota – jeśli zdołasz przeżyć.', 0),
(12933, 'koKR', 'Łał! Kiedy pierwszy raz zobaczyłem Smrodobrodego, myślałem, że już po tobie! Dobra robota!', 0),
(12934, 'koKR', 'Niewiarygodne! Myślałem, że całe to miejsce wyleci w powietrze, kiedy to coś się pojawiło! Naprawdę $gzdominowałeś:zdominowałaś; tę rundę!', 0),
(12935, 'koKR', 'Przez chwilę się o ciebie martwiłem, $N. Kiedy wyciągnął foki i pingwiny... No cóż, szczerze mówiąc, nie wiedziałem, co o tym myśleć. Wyglądało to cholernie niedorzecznie.', 0),
(12936, 'koKR', 'Do licha, pamiętam Korraka z dawnych czasów, kiedy jako młodzik pracowałem dla Klanu Mroźnego Wilka. Nigdy nie zamykał gęby! Chyba $gwyświadczyłeś:wyświadczyłaś; właśnie światu wielką przysługę, $N.', 0),
(12948, 'koKR', 'Udało ci się, $N! To była najbardziej emocjonująca walka ze wszystkich! Co zrobisz z wygraną? Ja? Jadę do Dalaranu i przepuszczę wszystko w Podbrzuszu. Tam na dole dużo się dzieje!', 0),
(12954, 'koKR', 'Hej! Znam cię. O twoim zwycięstwie w Kręgu Krwi mówiło się miesiącami! Szkoda, że $gstraciłeś:straciłaś; tytuł mistrza, kiedy nie $gpojawiłeś:pojawiłaś; się, żeby go obronić! Łatwo przyszło, łatwo poszło, co? Przynajmniej wciąż żyjesz.', 0),
(12974, 'koKR', 'Śliski cię przysłał, co?', 0),
(13096, 'koKR', '$GZrobiłeś:Zrobiłaś; to?! Gal\'daraha już nie ma?$b$bMasz, mon. Weź ten dar za to, że $gwymierzyłeś:wymierzyłaś; sprawiedliwość temu nędznikowi.', 0),
(13097, 'koKR', 'Słuchaj, mon. Trza tu zrobić niebezpieczną robotę!', 0),
(13098, 'koKR', '<Bah\'Kini przez chwilę przegląda grawerowane tablice, po czym znów zwraca się do ciebie.>$b$bTe są prawdziwe, $r. Umieszczę je na należnym miejscu w mojej kolekcji.$b$bMoże w końcu położymy kres takiemu postępowaniu.', 0),
(13099, 'koKR', 'Długoletnia uczennica? Ha!$b$bJeśli przez „długoletnia” rozumie całe moje życie, to chyba się zgadza.$b$bTo\'kini to mój tchórzliwy ojciec – za bardzo się boi, żeby zająć posterunek tak blisko Gundraku... więc wysłał mnie!', 0),
(13111, 'koKR', 'Aaa, tak, mon! O to mi chodziło.$b$bMasz – weź coś ładnego za fatygę.', 0),
(13449, 'koKR', 'Zbezcześć wielkie ognisko Przymierza w Zul\'Draku!', 0),
(13458, 'koKR', 'Zbezcześć wielkie ognisko Hordy w Zul\'Draku!', 0),
(13492, 'koKR', 'Uczcij płomień Zul\'Draku!', 0),
(13500, 'koKR', 'Uczcij płomień Zul\'Draku!', 0),
(13549, 'koKR', 'Doprawdy znakomite okazy, $N! Z pewnością dostarczą moim kolegom w domu wielu godzin ciekawych dociekań.', 0),
(13556, 'koKR', 'Raz, dwa, trzy... hehe, to dobra liczba, mon! Teraz będziemy bezpieczni na długo!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(12501, 'koKR', 'Jakie wieści z naszych posterunków, $N?', 0),
(12503, 'koKR', 'Może $gzniszczyłbyś:zniszczyłabyś; jeszcze kilku?', 0),
(12504, 'koKR', 'Musi się ich zameldować więcej.', 0),
(12505, 'koKR', 'O co tu chodzi?', 0),
(12506, 'koKR', 'Co $gwidziałeś:widziałaś;, $N?', 0),
(12508, 'koKR', 'Może zabijesz jeszcze kilku?', 0),
(12510, 'koKR', 'Masz cenne płyny?', 0),
(12512, 'koKR', '$GUratowałeś:Uratowałaś; naszych weteranów, $N?', 0),
(12514, 'koKR', 'Masz wszystkie grzyby?$B$BAch, i uważaj na bazyliszki, które tam czyhają.', 0),
(12516, 'koKR', 'Już po wszystkim?$B$BZmodyfikowane mojo zadziałało?$B$B$GPomściłeś:Pomściłaś; Sseratusa, zabijając jego proroka?', 0),
(12519, 'koKR', 'Masz te medale, $N?', 0),
(12527, 'koKR', 'Cóż to takiego?$B$BCzy przypadkiem nie $gwidziałeś:widziałaś; mojego nicponia ucznia, Pestlepota?$B$BWysłałem go w pewnej sprawie już dość dawno temu i wciąż nie wrócił!', 0),
(12541, 'koKR', 'Widzisz, $N, prawdziwa alchemia to coś znacznie więcej niż mieszanie kilku składników...', 0),
(12552, 'koKR', 'Nie, $N, to jeszcze nie koniec. Wiem na pewno, że po Kolramas wciąż chodzą nekromagowie.', 0),
(12553, 'koKR', 'Kądziołki muszą być nienaruszone, jeśli mam z nich złożyć urządzenie, którego da się użyć.', 0),
(12554, 'koKR', 'Nie mogę się doczekać, aż zatknę jego głowę na pice. Niech spróbuje się z tego podnieść!', 0),
(12555, 'koKR', 'Na pewno $gstrąciłeś:strąciłaś; ich dość? Czy ja wyglądam, jakbym chciała złapać zarazę?!', 0),
(12557, 'koKR', '$GOswoiłeś:Oswoiłaś; się już z moim laboratorium, $N?', 0),
(12562, 'koKR', 'Jeśli mogę coś zasugerować, może warto rozprawić się jeszcze z kilkoma wiążącymi wodę Drakkarów.', 0),
(12563, 'koKR', 'Jakie wieści z naszych posterunków, $N?', 0),
(12564, 'koKR', '$GZebrałeś:Zebrałaś; wodne maki, $N?', 0),
(12565, 'koKR', '<Zim\'Abwa wpatruje się nieprzeniknionym wzrokiem na północ i na południe.>', 0),
(12567, 'koKR', '<Kamienne oblicze Zim\'Abwy przeszywa ci duszę.$B$BZim\'Abwa jest zadowolony, ale chce, byś $gokazał:okazała; mu więcej wdzięczności i szacunku, składając kolejne ofiary Drakkarów.$B$BOdwdzięczy ci się tym samym.>', 0),
(12583, 'koKR', 'Masz części? Co? Masz?', 0),
(12584, 'koKR', 'Tak, $N?$b$bPowiedz, proszę, że masz saronit, o którego zdobycie prosiliśmy kapitana Ruperta.', 0),
(12585, 'koKR', 'Masz drewno na ogień, $N?', 0),
(12587, 'koKR', 'Jakie wieści z naszych posterunków, $N?', 0),
(12596, 'koKR', '$GSpotkałeś:Spotkałaś; się z każdym z moich kapitanów, $N?', 0),
(12597, 'koKR', '$GZebrałeś:Zebrałaś; wodne maki, $N?', 0),
(12598, 'koKR', '$GZasypałeś:Zasypałaś; tunele nerubian, $N?', 0),
(12599, 'koKR', 'Masz drewno na ogień, $N?', 0),
(12606, 'koKR', '$GUwolniłeś:Uwolniłaś; naszych żołnierzy ze szponów nerubian?', 0),
(12609, 'koKR', '$GZebrałeś:Zebrałaś; odczynniki, których potrzebuję, $N?', 0),
(12610, 'koKR', '$GSkończyłeś:Skończyłaś; zbierać skrzydła nietoperzy dla Finklesteina?', 0),
(12615, 'koKR', '<Czujesz na sobie wzrok Matki Dobrobytu. Zastanawia się, co ktoś taki jak ty robi przed jej obliczem.>', 0),
(12618, 'koKR', '<Zim\'Torga patrzy beznamiętnie. Zastanawia się, czy pragniesz jej dalszego błogosławieństwa i uczcisz ją kolejnymi ofiarami Drakkarów.>', 0),
(12622, 'koKR', 'Skoro ty wracasz gadać z Ahunae, to pewnie masz cały ten skarb.', 0),
(12627, 'koKR', 'Wciąż nie mogę nawiązać kontaktu. Rytuał uzdrowicieli nadal trwa.$B$BWróć tam, proszę, i zakłóć każdy z ich kotłów.', 0),
(12629, 'koKR', '$GPrzyniosłeś:Przyniosłaś; mi składniki, o które prosiłem, $N?', 0),
(12630, 'koKR', 'Jak się trzyma ten but, $N?', 0),
(12632, 'koKR', 'Musisz uwolnić od udręki jeszcze więcej moich dzieci!', 0),
(12635, 'koKR', 'Drakkarowie są tak zajęci niszczeniem samych siebie, że byłoby szkoda, gdyby historyczne znaczenie ich imperium również przepadło.', 0),
(12639, 'koKR', 'Mam nadzieję, że $gprzyniosłeś:przyniosłaś; dość. Po tym, co im $gzrobiłeś:zrobiłaś;, ataki od strony Sadzawek Jin\'Alai stały się jeszcze bardziej desperackie.', 0),
(12640, 'koKR', 'Masz jeszcze parę szczelin do zamknięcia, zanim my znowu pogadać, $N.', 0),
(12643, 'koKR', '$GPrzyniosłeś:Przyniosłaś; składniki, o które prosiłem, $N?', 0),
(12646, 'koKR', 'Szybko, $N, masz moje mojo?', 0),
(12647, 'koKR', 'Jeśli wkrótce nie położysz kresu mojemu cierpieniu, $N, wszystko może przepaść.', 0),
(12648, 'koKR', 'No i co, $N?$b$b$GKupiłeś:Kupiłaś; tę flaszkę?', 0),
(12649, 'koKR', 'No i co, $N?$b$b$GKupiłeś:Kupiłaś; tę flaszkę?', 0),
(12650, 'koKR', 'Drakkarów nie sposób zrozumieć. To brutalni dzicy, którzy stoczyli się na samo dno.', 0),
(12652, 'koKR', 'Góle nakarmione, co?', 0),
(12655, 'koKR', '<Wyczuwasz, że Zim\'Rhuk ci nie ufa. Próbuje przywołać jednego ze swoich strażników.>', 0),
(12656, 'koKR', '<Zim\'Rhuk jest pod wrażeniem, a zarazem sfrustrowany, że po raz kolejny udało ci się wymknąć jego strażnikom. Przynajmniej na razie.>$B$B<Złóż przed nim ofiary, a znów udzieli ci swojego błogosławieństwa.>', 0),
(12659, 'koKR', 'Ahunae wie, że nie ma mowy, żeby $N tak szybko oskalpować tylu z Heb\'Drakkar.', 0),
(12661, 'koKR', '$GZdobyłeś:Zdobyłaś; zaufanie ich dowódcy, $N?', 0),
(12662, 'koKR', 'On wciąż żyje. Nadal słyszę stąd jego wrzaski!', 0),
(12663, 'koKR', 'Ty i ja weźmiemy Gundrak, mon.', 0),
(12664, 'koKR', '$GObejrzałeś:Obejrzałaś; już pole bitwy, mon?', 0),
(12665, 'koKR', 'Na co jeszcze czekasz, $N?', 0),
(12666, 'koKR', 'Nigdy nie sądziłam, że do tego dojdzie. Drakkarowie są naprawdę straceni.', 0),
(12668, 'koKR', 'Czemu wracasz, skoro twoje zadanie nie zostało jeszcze wykonane? Nie rozumiesz, że mogę cię zniszczyć jedną myślą?$B$BIdź, robaczku. Wykonaj to, co ci rozkazałam!', 0),
(12669, 'koKR', 'Proszę, $N, powiedz, że nie $gzdradziłeś:zdradziłaś; się...', 0),
(12672, 'koKR', 'Szkoda, że Har\'koa nie przysłała cię wcześniej. Z drugiej strony nigdy się nie dogadywałyśmy.$b$bPewnie wstrzymywała twoją pomoc akurat tak długo, żeby do tego doszło.', 0),
(12673, 'koKR', '$GZrobiłeś:Zrobiłaś; porządek z moimi podwładnymi, $n?', 0),
(12674, 'koKR', 'MASZ MNIE ZA GŁUPIĄ?$B$BONI WCIĄŻ ŻYJĄ!', 0),
(12676, 'koKR', 'Udało ci się zniszczyć te wozy Plagi, $N?', 0),
(12677, 'koKR', 'Witaj z powrotem, $n.$b$bUdało ci się ukraść jakieś próbki kryształów Drakuru?', 0),
(12684, 'koKR', 'Chciałabym, żebyśmy mogli coś zrobić, by przywrócić Mam\'totha do życia, ale nie możemy.$b$bMożemy uczcić jego i jego ofiarę, walcząc dalej z Drakkarami.', 0),
(12685, 'koKR', 'Co cię do mnie sprowadza, $N?', 0),
(12686, 'koKR', 'Darmuk zapłacił za swoją porażkę, $n?', 0),
(12690, 'koKR', '$GRozgromiłeś:Rozgromiłaś; trolle, $n?', 0),
(12707, 'koKR', 'Co? Już po wszystkim?$B$B$GWymierzyłeś:Wymierzyłaś; wełniastą sprawiedliwość tym żałosnym lodowym trollom?', 0),
(12708, 'koKR', 'Chyba nie $gporadziłeś:poradziłaś; sobie tak szybko ze wszystkimi zaczarowanymi wojownikami tiki?', 0),
(12709, 'koKR', 'Może masz już skrytki w swoim plecaku?', 0),
(12710, 'koKR', '$GPoszedłeś:Poszłaś; zobaczyć moje dzieła, $N?', 0),
(12712, 'koKR', 'Nie potrafię dość mocno podkreślić, jak ważne jest, byś $gzdobył:zdobyła; klucz wodza bez względu na koszty.', 0),
(12713, 'koKR', '$GStanąłeś:Stanęłaś; do walki z Drakuru, $n?', 0),
(12729, 'koKR', 'Masz to, czego trzeba, $N?', 0),
(12730, 'koKR', 'Mogę ci ofiarować jedynie ciepło moich słów i otuchę, jaką ze sobą niosą.$B$BWeź tyle czasu, ile potrzebujesz, by się zahartować i przygotować, ale błagam, nie zwlekaj zbyt długo, bo prorok z pewnością spadnie na nas.', 0),
(12740, 'koKR', 'Skoro $gwróciłeś:wróciłaś; tu, żeby ze mną rozmawiać, to czemu wciąż widzę, jak moi ludzie spadają na śmierć?', 0),
(12799, 'koKR', 'Dzień dobry, $r.$b$b$GZebrałeś:Zebrałaś; ektoplazmę, o którą prosił Finklestein?', 0),
(12857, 'koKR', 'Biedny Wściekłogrzywy. On być prezent od szwagra.', 0),
(12859, 'koKR', 'Hrm, zgasić pożary?', 0),
(12861, 'koKR', 'Ty uratować Wściekłe Pazury?', 0),
(12883, 'koKR', 'Drakuru, co? Słyszałem już to imię...', 0),
(12884, 'koKR', 'Co tam masz, $r?', 0),
(12901, 'koKR', 'Naprawdę nie wiem, czy ten plan się uda, $N. Po prostu przynieś mi złom, a zrobię, co w mojej mocy.', 0),
(12904, 'koKR', 'Wyświadczasz światu przysługę, $gprzyjacielu:przyjaciółko;. Te potwory trzeba powstrzymać!', 0),
(12914, 'koKR', 'Bez plastyfikatorów i stabilizatorów nigdy nie zrobię materiałów wybuchowych potrzebnych, żeby wyciągnąć twojego przyjaciela z pudła.', 0),
(12916, 'koKR', 'Jestem olbrzymem, który dotrzymuje słowa, mała istoto.', 0),
(12919, 'koKR', 'Co się dzieje? Nasi wrogowie nie żyją?', 0),
(12954, 'koKR', 'Nie ma wypłaty, dopóki walka się nie skończy, $gczłowieku:kobieto;.', 0),
(13096, 'koKR', 'Czy śmierć Akaliego została pomszczona, $r?', 0),
(13098, 'koKR', '$GZnalazłeś:Znalazłaś; tablice z historią Drakkarów, mon?', 0),
(13111, 'koKR', 'Masz dla mnie kawałek tego golema, mon?', 0),
(13549, 'koKR', 'Nie, tak nie może być. Wróć, proszę, gdy będziesz mieć samice lampartów i niedźwiedzi, których potrzebuję na długą i trudną podróż do domu.', 0),
(13556, 'koKR', 'Kto by pomyślał, że wielki Dubra\'Jin zechce tyle jaj? I co on z nimi w ogóle zrobi?', 0);
