INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3279, 'koKR', 'Sługi, słuchać wezwania swego pana! Król Lisz dać Drakuru pełną władzę nad armiami Plagi w Zul\'Draku. Mamy rozkaz zabić wszystko.$B$BWSZYSTKO MUSI ZGINĄĆ!$B$BPrzerabiamy wszystkie trupy na Martwych Polach i wysyłamy je ekipie księcia Navariusa w Zeramas do uplagowienia! Nic się nie zmarnuje, póki Drakuru pilnuje!$B$BWkrótce będziemy pić krew proroków, by stać się silniejsi niż kiedykolwiek! Zul\'Drak i Gundrak padną przed Plagą!', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(27422, 'koKR', 'Witaj w Reducie Argentu, $N.$b$bCzuj się jak u siebie, ale nie rozgaszczaj się za bardzo. Jeszcze nie wyszliśmy na prostą – daleko nam do tego.$b$bJeśli mamy wyjść stąd w jednym kawałku, każdy będzie musiał zrobić swoje... ty też.', '', 0),
(27424, 'koKR', 'Ale się wpakowaliśmy.', '', 0),
(27425, 'koKR', 'Ziemię kala obecność Plagi z jednej strony i rytuały Drakkarów z drugiej.$B$BA my stoimy niewzruszenie pomiędzy nimi.', '', 0),
(27426, 'koKR', 'Dzięki Światłości, że jesteś!', 'Dzięki Światłości, że jesteś!', 0),
(27427, 'koKR', 'Witaj, $N. Jesteśmy tu w samym środku bitwy.', 'Witaj, $N. Jesteśmy tu w samym środku bitwy.', 0),
(27429, 'koKR', 'Czy ty nie jesteś $n? Słyszałem, że nie żyjesz.', 'Czy ty nie jesteś $n? Słyszałem, że nie żyjesz.', 0),
(27430, 'koKR', 'Mów szybko... walki są tu zażarte. Muszę zachować czujność.', 'Mów szybko... walki są tu zażarte. Muszę zachować czujność.', 0),
(27431, 'koKR', 'Nowy rekrut? To nie jest regulaminowa zbroja.', 'Nowy rekrut? To nie jest regulaminowa zbroja.', 0),
(27432, 'koKR', 'O, dobrze, posiłki!', 'O, dobrze, posiłki!', 0),
(27433, 'koKR', 'Masz dla mnie wiadomość?', 'Masz dla mnie wiadomość?', 0),
(27434, 'koKR', 'Żołnierzu, masz nowe rozkazy. Masz się wycofać i zameldować u sierżanta!', 'Żołnierzu, masz nowe rozkazy. Masz się wycofać i zameldować u sierżanta!', 0),
(27439, 'koKR', 'Trochę tu goręcej, niż się $gspodziewałeś:spodziewałaś;, $r?$b$bNie powiem, żeby mnie to dziwiło. Słyszę to od prawie każdego, kto dotrze aż tutaj.', '', 0),
(27441, 'koKR', 'Jestem Ubungo. Reprezentuję plemię Zandalarów.$B$BDzieje się coś złego, $r. Drakkarowie tym, co knują, sami sprowadzą na siebie zgubę.$B$BNiektóre trolle nigdy się nie nauczą.', '', 0),
(27446, 'koKR', 'Jasne. W takim razie lepiej wrócę do sierżanta.', 'Jasne. W takim razie lepiej wrócę do sierżanta.', 0),
(27447, 'koKR', 'Do zobaczenia.', 'Do zobaczenia.', 0),
(27448, 'koKR', 'Uważaj na siebie. Ci Drakkarowie to paskudna banda.', 'Uważaj na siebie. Ci Drakkarowie to paskudna banda.', 0),
(27449, 'koKR', 'Ostrożnie tutaj, $N. Te trolle zabiły własnego boga węży!', 'Ostrożnie tutaj, $N. Te trolle zabiły własnego boga węży!', 0),
(27451, 'koKR', 'Ciekawe, dokąd nas teraz poślą. I kto się zajmie tymi tutaj?', 'Ciekawe, dokąd nas teraz poślą. I kto się zajmie tymi tutaj?', 0),
(27452, 'koKR', 'Z tymi Drakkarami są same kłopoty. Musimy się stąd wynosić i ruszać do Twierdzy Sprawiedliwości!', 'Z tymi Drakkarami są same kłopoty. Musimy się stąd wynosić i ruszać do Twierdzy Sprawiedliwości!', 0),
(27476, 'koKR', 'Doprawdy, tutejsze okropności przewyższają te, które przeżyliśmy na Plagowiskach.$b$bPlaga jest teraz potężniejsza niż kiedykolwiek.', '', 0),
(27477, 'koKR', 'Nie mogę już tego znieść...$b$bNajpierw cię zabijają, a potem zjadają! I to jeszcze jak masz szczęście!', 'Nie mogę już tego znieść...$b$bNajpierw cię zabijają, a potem zjadają! I to jeszcze jak masz szczęście!', 0),
(27478, 'koKR', 'Musisz mi pomóc się stąd wydostać, $r!$b$bNie chcę się stać taki jak oni!', 'Musisz mi pomóc się stąd wydostać, $r!$b$bNie chcę się stać taki jak oni!', 0),
(27479, 'koKR', 'Odkąd tu jestem, nie mogę ani jeść, ani spać.$b$bPo prostu nie nadaję się do Krucjaty...', 'Odkąd tu jestem, nie mogę ani jeść, ani spać.$b$bPo prostu nie nadaję się do Krucjaty...', 0),
(27480, 'koKR', '<szloch> Mój wuj służył w Argentowym Brzasku.$b$bJak on mógł stawiać czoła tym plugastwom?', '<szloch> Mój wuj służył w Argentowym Brzasku.$b$bJak on mógł stawiać czoła tym plugastwom?', 0),
