(28802, 'koKR', 'BRRRRRR!', '', 0),
(28803, 'koKR', '%s wybucha!', '', 0),
(28833, 'koKR', 'Co? Jak to możliwe?', '', 0),
(28837, 'koKR', 'Cóż to, ty żałosny robaczku? $GPrzyszedłeś:Przyszłaś; tu zginąć?', '', 0),
(28838, 'koKR', 'Rozpoznaję twój smród. To ty $gprzemknąłeś:przemknęłaś; obok mnie na grzbiecie tego nędznego śnieżnego lamparta!', '', 0),
(28855, 'koKR', 'NIEEEEeeeeeeeeeeeeeeeee!', '', 0),
(28858, 'koKR', 'Twoje przebranie mnie nie zwiedzie, ty worku mięsa! Twoja klęska ucieszy Drakuru!', '', 0),
