(29040, 'koKR', 'Masz zaczarowane tiki? $GZABIŁEŚ:ZABIŁAŚ; MOJĄ RODZINĘ!', '', 0),
(29041, 'koKR', 'ZABIJĘ CIĘ, $n!', '', 0),
(29177, 'koKR', 'JESTEM WOLNY, MALUTKI DRAKKARZE. CZAS ZAPŁACIĆ ZA WASZE LICZNE WYSTĘPKI!', '', 0),
(29181, 'koKR', '$n! Czekałem na twój powrót. Co ci tak długo zajęło, mon?$b$bCzas dokończyć przemianę trolli o skażonej krwi.$b$bChodź ze mną i zobacz, jak powstaje nasza armia!', '', 0),
(29182, 'koKR', 'Jestem $ggotów:gotowa; ci towarzyszyć, Drakuru.', 'Jestem $ggotów:gotowa; ci towarzyszyć, Drakuru.', 0),
(29237, 'koKR', '', 'Nie, tylko nie Akali!', 0),
(29250, 'koKR', 'Co to? Poznaję cię – widziałem cię, kiedy zabijałem Akaliego. To pewnie ty jesteś $n, przed $gktórym:którą; wszyscy drżą.', '', 0),
(29251, 'koKR', 'Nie martwisz mnie, $gchłopcze:dziewczyno;. Wręcz przeciwnie – nie mogę się doczekać, aż cię zabiję. Nic już nie stanie między mną a Zim\'Torga!', '', 0),
(29253, 'koKR', 'Jaka szkoda, że dopiero teraz pojmujesz prawdę – władam mocą boga. Ty jesteś $gzwykłym śmiertelnikiem:zwykłą śmiertelniczką;. Nie masz szans mnie pokonać!', '', 0),
(29256, 'koKR', '$GWtrąciłeś:Wtrąciłaś; się w sprawy, które nie były twoje. Nie jesteś nikim więcej niż obcym najeźdźcą. Szykuj się na śmierć!', '', 0),
(29257, 'koKR', 'Prorok zaczyna odprawiać rytuał unicestwienia.', '', 0),
(29271, 'koKR', 'Co? HAR\'KOA?!', '', 0),
(29273, 'koKR', 'Niech będzie, kociaku. Nie widzę potrzeby odwlekać twojej nieuniknionej zguby. Z przyjemnością zajmę się tobą, jak tylko wykończę tego głupca!', '', 0),
(29275, 'koKR', 'NIE! Nie zostanę pokonany!', '', 0),
(29281, 'koKR', 'Dobrze się przyjrzyj temu miejscu, mon. Pomożesz mi je podbić!', '', 0),
(29291, 'koKR', 'O tak, mon! Tu czeka wielka chwała!', '', 0),
(29292, 'koKR', 'Król Lisz dzieli się swoją mocą z tymi, którzy dobrze mu służą, mon.', '', 0),
(29293, 'koKR', 'Przyjdź do mnie teraz, $n. Muszę z tobą pomówić.', '', 0),
(29424, 'koKR', '', 'Uważam cię za $gniegodnego:niegodną;.', 0),
(29426, 'koKR', '', 'Błagaj o życie. Proś. Nic ci to nie da!', 0),
(29427, 'koKR', '', 'Wieczne potępienie to twoja przyszłość.', 0),
(29428, 'koKR', '', '$GZabiłeś:Zabiłaś; mnie, a teraz ja zabiję ciebie... raz za razem!', 0),
(29429, 'koKR', '', 'Nie ma ucieczki. Jest tylko mój gniew!', 0),
(29430, 'koKR', '', 'Mój wyrok jest ostateczny.', 0),
(29431, 'koKR', '', 'Płoń w ogniu mojej furii!', 0),
(29441, 'koKR', 'Patrz, mon! Tworzymy największą armię Plagi, jaką widział świat!', '', 0),
(29442, 'koKR', 'To pierwsi z wielu! Przemkniemy przez Zul\'Drak jak wiatr...', '', 0),
(29831, 'koKR', '$GZgubiłem:Zgubiłam; zaczarowany obcisły naszyjnik!', '$GZgubiłem:Zgubiłam; zaczarowany obcisły naszyjnik!', 0),
(29853, 'koKR', 'Proszę, $n.$b$bA teraz, proszę, wróć do swojego zadania...', '', 0),
(29885, 'koKR', 'Co to za zdrada?! Zapłacisz za to oszustwo życiem, mon!', '', 0),
(29886, 'koKR', 'Berło dominacji jasno świeci! Użyj go teraz!', '', 0),
(29916, 'koKR', 'Głupcze! $GMogłeś:Mogłaś; mieć wielką moc, mon!', '', 0),
(29917, 'koKR', 'Jak to możliwe? Król Lisz mówił, że ma wobec ciebie wielkie plany, mon...', '', 0),
(29918, 'koKR', 'Powinienem był wiedzieć, żeby nikomu nie ufać!', '', 0),
(29919, 'koKR', '$GOdwróciłeś:Odwróciłaś; się plecami do przeznaczenia, mon. Teraz zginiesz!', '', 0),
(29920, 'koKR', 'Twoja zdrada ani trochę mnie nie spowolni, mon.', '', 0),
(29921, 'koKR', 'Nigdy cię nie potrzebowałem, mon. Zmiażdżę Zul\'Drak bez ciebie!', '', 0),
(29922, 'koKR', 'DOŚĆ!', '', 0),
(29923, 'koKR', 'Ta głupia zdrada kosztowała cię twoje przeznaczenie!', '', 0),
(29969, 'koKR', 'Panie, ten śmiertelny szczur nas zdradził. Musi cierpieć!', '', 0),
(30371, 'koKR', 'TROLL ROBIĆ MNIE ZŁY!', '', 0),
(30396, 'koKR', 'Wściekły Pazur wolny! Troll teraz ginąć!', '', 0),
(30397, 'koKR', 'Koniec z miłym wolvarem!', '', 0),
(30398, 'koKR', 'Robię kupę na was, trolle!', '', 0),
(30399, 'koKR', 'Zemsta za Wściekłe Pazury!', '', 0),
(30400, 'koKR', 'ARRRROOOOOGGGGAAAA!!!', '', 0),
(30401, 'koKR', 'To znaczyć wojna!', '', 0),
(30433, 'koKR', 'Rozejrzyj się i pozwól, by ogrom zniszczeń do ciebie dotarł, $N. Każdy troll, który tu mieszkał, albo nie żyje, albo uciekł na wyższe poziomy.$B$BA będzie jeszcze gorzej.$B$BW akcie desperacji żyjące trolle Drakkarów złożyły w ofierze własnych bogów zwierząt, by pić z ich krwi i zyskać niewyobrażalną moc. Choć dzięki nowej sile zdołały powstrzymać Plagę, skutki okazały się katastrofalne. Dowodem jest starożytne imperium Zul\'Drak, które leży w ruinie.\n', '', 0),
(30449, 'koKR', 'Gerk, Burr, Dargath: wszyscy zginęli... Zostaliśmy tu tylko MacKellar i ja. Mam nadzieję, że $gprzyniosłeś:przyniosłaś; jakieś dobre wieści.', '', 0),
(30450, 'koKR', 'Możesz naprawić mój ekwipunek?', 'Możesz naprawić mój ekwipunek?', 0),
(30482, 'koKR', 'Proszę być cicho! Szczeniaki spać!', '', 0),
(30491, 'koKR', 'Brzydkie małe potwory, módlcie się, żebym się stąd nie wydostał!', '', 0),
(30492, 'koKR', 'Zmiażdżę was wszystkich!', '', 0),
(30493, 'koKR', 'Nędzne bestie!', '', 0),
(30494, 'koKR', 'Moi bracia po mnie przyjdą i wtedy zobaczycie, czym jest prawdziwa potęga!', '', 0),
(30495, 'koKR', 'Wasze tortury tylko podsycają mój gniew!', '', 0),
(30496, 'koKR', 'Pożrę was w całości!', '', 0),
(30497, 'koKR', 'Jak myślicie, jak długo ta klatka mnie utrzyma, pomioty?!', '', 0),
(30599, 'koKR', 'WOLNY!!! Wkrótce poczujecie gniew burzowego króla!', '', 0),
(30609, 'koKR', 'Wraz z moją wolnością nadchodzi zemsta burzy!', '', 0),
(30610, 'koKR', 'Zanim zaczniemy, posłuchaj, co mam ci do powiedzenia o naszym wrogu. Nie chcesz być $gnieprzygotowany:nieprzygotowana;, gdy będziemy w polu miażdżyć Plagę.', '', 0),
(30615, 'koKR', 'Gymerze, gdzie są Algar, Navarius i Thrym?', 'Gymerze, gdzie są Algar, Navarius i Thrym?', 0),
(30616, 'koKR', 'Gymerze, co muszę wiedzieć? Nigdy nie $gjechałem:jechałam; na olbrzymie.', 'Gymerze, co muszę wiedzieć? Nigdy nie $gjechałem:jechałam; na olbrzymie.', 0),
(30617, 'koKR', 'Jestem $ggotów:gotowa;, Gymerze. Ruszajmy!', 'Jestem $ggotów:gotowa;, Gymerze. Ruszajmy!', 0),
(30633, 'koKR', 'Władca bitewny Ymirjarów, Algar Wybraniec, podburza swoje armie wargulów w Relikwiarzu Bólu, na północny wschód od tej klatki.$B$BKsiążę Navarius jest po drugiej stronie Martwych Pól, na wschód stąd, niedaleko wielkich schodów prowadzących na drugi poziom Zul\'Draku.$B$BGdzie jest Thrym, na razie nie wiadomo, co jest dziwne, zważywszy na jego rozmiary.$B$BTrzeba się rozprawić z nimi wszystkimi!', '', 0),
(30634, 'koKR', 'Mam jeszcze kilka pytań, Gymerze.', 'Mam jeszcze kilka pytań, Gymerze.', 0),
(30648, 'koKR', 'Kiedy będziesz $ggotów:gotowa;, posadzę cię na swojej głowie i ruszymy w samo serce Plagi w Zul\'Draku. Musisz mnie kierować, bym miażdżył i niszczył naszych wrogów!', '', 0),
(30655, 'koKR', 'Wpakowaliśmy się po uszy, $r! Uważaj na siebie!', '', 0),
(30656, 'koKR', 'PANIE! NIE!', '', 0),
(30657, 'koKR', 'THRYM MIAŻDŻYĆ!', '', 0),
(30658, 'koKR', 'Thrymie... Po... Pomścij mnie...', '', 0),
(30659, 'koKR', 'Och, więc go $guwolniłeś:uwolniłaś;, tak? Nieważne, jego śmierć i przebudowa opóźnią się tylko odrobinę.', '', 0),
(30675, 'koKR', 'Padli jak worek orczych czaszek!', '', 0),
(30676, 'koKR', 'Z pretendenta została tylko czerwona plama na podłodze!', '', 0),
(30677, 'koKR', 'Wołajcie klaunów! Zrobił się tam istny cyrk!', '', 0),
(30678, 'koKR', 'UUUCH! Tego trzeba będzie zeskrobywać „skrobaczką”.', '', 0),
(30679, 'koKR', 'ZNIKĄD – ŁUP! TRUP!', '', 0),
(30680, 'koKR', 'Odwróćcie wzrok, panie i panowie! To istna rzeź!', '', 0),
(30681, 'koKR', 'Wielki Amfiteatr Męczarni czeka, $n. Pamiętaj, że gdy walka się zacznie, musisz zostać na arenie. WYGRANA ALBO ŚMIERĆ!', '', 0),
(30682, 'koKR', 'Oto znów jesteśmy tutaj, panie i panowie. Epicka walka życia ze śmiercią w Amfiteatrze Męczarni! W tej rundzie $n kontra potężny jormungar Yg... Yggd? Yggdrzem? Kto wymyśla te imiona?! $n kontra wielki robal!', '', 0),
(30684, 'koKR', '$n $gpokonał:pokonała; Yg... Yggg... naprawdę wielkiego robala!', '', 0),
(30685, 'koKR', 'Szykuj się do walki, $n! Wejdź do amfiteatru i bądź $ggotów:gotowa;! Pamiętaj, że ty i twój przeciwnik musicie przez cały czas pozostawać na arenie, inaczej zostaniecie zdyskwalifikowani!', '', 0),
(30686, 'koKR', 'Walka zaraz się zacznie! Czy dobrze czytam tę kartkę? To... to nikczemny lord magnataurów, SMRODOBRODY! Tak, moi drodzy, SMRODOBRODY! $n nie ma żadnych szans!', '', 0),
(30687, 'koKR', 'I z pełną STANOWCZOŚCIĄ $n rozprawia się z lordem magnataurów! Klan Smrodobrodego będzie za nim tęsknił w domu, na Smoczych Pustkowiach!', '', 0),
(30698, 'koKR', 'Czujecie to, moi drodzy? Powietrze aż trzeszczy od energii! To może oznaczać tylko jedno...', '', 0),
(30703, 'koKR', 'Tę walkę trzeba zobaczyć, żeby w nią uwierzyć! Nasz następny zawodnik był niegdyś łagodnym kiełzarskim rybakiem, ale został bezdusznym najemnikiem, gdy całą jego rodzinę wybiło okrutne stado lwów morskich i wrednych pingwinów! Teraz walczy już tylko dla złota! Panie i panowie, ORINOKO ŁAMIKIEŁ!!', '', 0),
(30707, 'koKR', 'Z Dzikiego Występu w Lodowej Koronie – Vladof Rzeźnik i jego mamut Enormos! Z naszych pretendentów nic nie zostanie, moi drodzy! Szykujcie się na ulewę krwi, flaków i łez!', '', 0),
(30714, 'koKR', 'Czempion trolli z Zimowego Topora rzucił ci wyzwanie, $n! Mam nadzieję, że jesteś $ggotów:gotowa;!', '', 0),
(30715, 'koKR', 'Prosto z odległych Gór Alterak, jeden z najgroźniejszych zawodników, jakich widziała ta arena: KORRAK KRWAWY SZALENIEC!!!', '', 0),
(30716, 'koKR', 'NIE WIERZĘ! MAMY NOWEGO CZEMPIONA MĘKI!!! Vladofa Rzeźnika pokonała zbieranina nikomu nieznanych płotek! Niesamowity finał!', '', 0),
(30718, 'koKR', '$n zostaje $gnabity:nabita; na róg!', '', 0),
(30754, 'koKR', 'Wyglądasz na kogoś, kto mógłby nam zarobić trochę kasy. Co powiesz na rundkę w Amfiteatrze Męczarni, $gkolego:koleżanko;?', '', 0),
(30756, 'koKR', 'Jesteś teraz $gczempionem:czempionką;, $gkolego:koleżanko;! Myślisz, że masz to, czego trzeba, by obronić tytuł?', '', 0),
(30829, 'koKR', 'Przekąski na sprzedaż!', 'Przekąski na sprzedaż!', 0),
(30830, 'koKR', 'Przekąski!', 'Przekąski!', 0),
(30831, 'koKR', 'Przekąski, tu kupicie przekąski!', 'Przekąski, tu kupicie przekąski!', 0),
(30832, 'koKR', 'Przekąski! Tu kupicie przekąski!', 'Przekąski! Tu kupicie przekąski!', 0),
(30833, 'koKR', 'Popcorn! Kupujcie popcorn!', 'Popcorn! Kupujcie popcorn!', 0),
(30834, 'koKR', 'Orzeszki! Tu kupicie orzeszki!', 'Orzeszki! Tu kupicie orzeszki!', 0),
(30835, 'koKR', 'Piwo Męczarni! Zimne Piwo Męczarni!', 'Piwo Męczarni! Zimne Piwo Męczarni!', 0),
(30836, 'koKR', 'Popcorn! Orzeszki! Piwo!', 'Popcorn! Orzeszki! Piwo!', 0),
(31126, 'koKR', 'DOŚĆ!', '', 0),
(31300, 'koKR', 'Gdzie jest Nestor Ohanzee?', 'Gdzie jest Nestor Ohanzee?', 0),
(31301, 'koKR', 'Nestor Ohanzee przebywa w Gundraku.', 'Nestor Ohanzee przebywa w Gundraku.', 0),
(31302, 'koKR', 'Gdzie jest Nestor Szarogrzywy?', 'Gdzie jest Nestor Szarogrzywy?', 0),
(31303, 'koKR', 'Nestora Szarogrzywego widziano ostatnio w K3 na Burzowych Szczytach.', 'Nestora Szarogrzywego widziano ostatnio w K3 na Burzowych Szczytach.', 0),
(31304, 'koKR', 'Gdzie jest Nestor Muraco?', 'Gdzie jest Nestor Muraco?', 0),
(31305, 'koKR', 'Nestor Muraco przebywa tuż pod Obozem Tunka\'lo na Burzowych Szczytach.', 'Nestor Muraco przebywa tuż pod Obozem Tunka\'lo na Burzowych Szczytach.', 0),
(31382, 'koKR', 'To czarny dzień w dziejach trolli, mon.', '', 0),
(31383, 'koKR', 'To straszne, mon. Nie mogę na to patrzeć.', '', 0),
(31392, 'koKR', '', 'Moim obowiązkiem jest spisać te tragiczne wydarzenia dla dobra przyszłych pokoleń.', 0),
(32534, 'koKR', 'Wypruję ci flaki, mon!', '', 0),
(32535, 'koKR', 'Nic z ciebie po tym nie zostanie!', '', 0),
(32536, 'koKR', 'Chcesz zobaczyć moc? Pokażę ci moc!', '', 0),
(32537, 'koKR', 'Wypatroszyć ich! Nabić ich na pal!', '', 0),
(32538, 'koKR', 'ZABIĆ ICH WSZYSTKICH!', '', 0),
(32539, 'koKR', 'Przywitaj się z moim WIELKIM przyjacielem!', '', 0),
(32540, 'koKR', 'Ale jazda!', '', 0),
(32541, 'koKR', 'Po co nam bogowie, skoro to MY jesteśmy bogami?', '', 0),
(32542, 'koKR', 'A nie mówiłem!', '', 0),
(32543, 'koKR', 'Nawet potężni... mogą upaść.', '', 0),
(33189, 'koKR', 'Mroźny lampart leży tu uśpiony.', '', 0),
(33190, 'koKR', 'Podnieś ogon mroźnego lamparta, by sprawdzić, czy to samiec, czy samica.', 'Podnieś ogon mroźnego lamparta, by sprawdzić, czy to samiec, czy samica.', 0),
(33191, 'koKR', 'To rozzłoszczony samiec!', '', 0),
(33192, 'koKR', 'To samica.', '', 0),
(33193, 'koKR', 'Lodowołapy niedźwiedź leży tu uśpiony.', '', 0),
(33194, 'koKR', 'Podnieś ogon lodowołapego niedźwiedzia, by sprawdzić, czy to samiec, czy samica.', 'Podnieś ogon lodowołapego niedźwiedzia, by sprawdzić, czy to samiec, czy samica.', 0),
(33234, 'koKR', 'Ale się wpakowaliśmy. Już dawno powinniśmy dołączyć do naszych sił w Lodowej Koronie, a teraz ugrzęźliśmy w tej klęsce, wciśnięci między Plagę a Drakkarów.$B$BMówiłem najwyższemu lordowi, że przybycie tutaj to błąd.$B$BZobacz, czy możesz tam jakoś pomóc.', '', 0),
(33235, 'koKR', 'Słyszysz to, $N? Żywioły krzyczą, że ta ziemia prawie umarła. Drakkarowie kradną moc swoich bogów, zabijając ich tylko po to, by bronić się przed Plagą.$B$BSą krótkowzroczni i w końcu sami doprowadzą się do zguby.', '', 0),
(33236, 'koKR', '', 'Po Plagowiskach i bitwie o Kaplicę Świetlistej Nadziei nie sądziłam, że zobaczymy coś straszniejszego.$B$BMyliłam się.', 0),
(34002, 'koKR', 'Juchowór pokazał mi Imperium Drakkarów. Chętnie pomogę ci je podbić!', 'Juchowór pokazał mi Imperium Drakkarów. Chętnie pomogę ci je podbić!', 0),
(34003, 'koKR', 'Wszystko w swoim czasie, mon. Wkrótce będę miał dla ciebie więcej roboty...', '', 0),
(34005, 'koKR', '$GZaprowadziłem:Zaprowadziłam; porządek wśród fantomów zarazy!', '$GZaprowadziłem:Zaprowadziłam; porządek wśród fantomów zarazy!', 0),
(34007, 'koKR', 'Owszem, mon. Nasze zapasy kryształów zarazy już prawie wystarczą!', '', 0),
(34008, 'koKR', '$GPokonałem:Pokonałam; Darmuka! Jak jeszcze mogę ci służyć?', '$GPokonałem:Pokonałam; Darmuka! Jak jeszcze mogę ci służyć?', 0),
(34010, 'koKR', 'Niekompetencja Darmuka już nam nie przeszkodzi! Cierpliwości, mon. Wkrótce będzie dla ciebie więcej do zrobienia...', '', 0),
(34011, 'koKR', 'Wodzowie Drakkarów zostali pojmani! Co jeszcze mam zrobić?', 'Wodzowie Drakkarów zostali pojmani! Co jeszcze mam zrobić?', 0),
(34019, 'koKR', 'Z wodzami z drogi jesteśmy gotowi do ataku! Wkrótce, $n...', '', 0),
(34020, 'koKR', '$GByłem:Byłam; świadkiem twojej wspaniałej operacji, Drakuru. Kiedy wprowadzimy twój plan w życie?', '$GByłem:Byłam; świadkiem twojej wspaniałej operacji, Drakuru. Kiedy wprowadzimy twój plan w życie??', 0),
(34021, 'koKR', 'Teraz wiesz już wszystko, mon! Przygotuj się... wkrótce atakujemy!', '', 0),
(35005, 'koKR', '$n? Słyszałem, że nie żyjesz.', '$n? Słyszałem, że nie żyjesz.', 0);
